var DATA = {"choice":[{"no":1,"stem":"我们把提供电能的的装置叫做（ ）。","options":["电源","电动势","发电机","电动机"],"answer":0,"explain":"电源是将其他形式能量转换为电能、向电路提供电能的装置。电动势是电源内部的物理量，发电机是电源的一种，电动机是消耗电能的负载。"},{"no":2,"stem":"能把正电荷从低电位移向高电位的力叫（ ）。","options":["电磁力","电场力","电源力","电动力"],"answer":2,"explain":"电源力（非静电力）在电源内部把正电荷从低电位（负极）移到高电位（正极），维持电路持续电流。电场力方向恰好相反，是推动电荷在外电路流动。"},{"no":3,"stem":"直流电路中，我们把电流流出的一端叫电源的","options":["正极","负极","端电压","电动势"],"answer":0,"explain":"规定电流从电源正极流出、经外电路流回负极，所以电流流出的一端是正极。"},{"no":4,"stem":"电荷的基本特性是（ ）。","options":["异性电荷相吸引，同性电荷相排斥","同性电荷相吸引，异性电荷相排斥","异性电荷和同性电荷都相吸引","异性电荷和同性电荷都相排斥"],"answer":0,"explain":"电荷间相互作用的基本规律：同性相斥、异性相吸。"},{"no":5,"stem":"在电路中，电流之所以能流动，是由电源两端的电位差造成的，我们把这个电位差叫做（ ）。","options":["电压","电源","电流","电容"],"answer":0,"explain":"电压即两点间的电位差，是推动电荷定向移动形成电流的原因。"},{"no":6,"stem":"在一恒压的电路中，电阻R增大，电流随之（ ）。","options":["减小","增大","不变","不一定"],"answer":0,"explain":"由欧姆定律 I=U/R，电压恒定时，电阻增大则电流减小。"},{"no":7,"stem":"几个电阻的两端分别接在一起，每个电阻两端承受同一电压，这种电阻连接方法称为电阻的（ ）。","options":["串联","并联","串并联","级联"],"answer":1,"explain":"并联的定义就是各电阻两端分别接在一起、承受同一电压。串联是首尾依次相连、电流相同。"},{"no":8,"stem":"金属导体的电阻与导体（ ）有关。","options":["长度","截面积","电阻率","材料"],"answer":2,"explain":"导体电阻 R=ρL/S，与电阻率、长度、截面积有关。其中电阻率由材料本身决定，是区别不同材料的本质参数。"},{"no":9,"stem":"正弦交流电的三要素是（ ）。","options":["电压、电动势、电位","最大值、频率、初相位","容抗、感抗、阻抗","平均值、周期、电流"],"answer":1,"explain":"正弦交流电的三要素是最大值（幅值）、频率（或角频率）、初相位，三者确定后正弦量即唯一确定。"},{"no":10,"stem":"电感在直流电路中相当于（ ）。","options":["开路","短路","断路","不存在"],"answer":1,"explain":"直流稳态下电流不变化，di/dt=0，电感两端电压 u=L·di/dt=0，相当于短路。"},{"no":11,"stem":"电容器中储存的能量是（ ）。","options":["热能","机械能","磁场能","电场能"],"answer":3,"explain":"电容器通过极板间的电场储存能量，属于电场能。电感储存的才是磁场能。"},{"no":12,"stem":"恒流源的特点是（ ）。","options":["端电压不变","输出功率不变","输出电流不变","内部损耗不变"],"answer":2,"explain":"恒流源的定义就是输出电流恒定不变，其端电压由外电路决定。与之对应，恒压源是端电压不变。"},{"no":13,"stem":"在电容电路中，通过电容器的是（ ）。","options":["直流电流","交流电流","直流电压","直流电动势"],"answer":1,"explain":"电容有'隔直通交'特性：直流稳态下电容相当于开路，只有交流电流能持续通过（以位移电流形式）。"},{"no":14,"stem":"全电路欧姆定律应用于（ ）。","options":["任一回路","任一独立回路","任何电路","简单电路"],"answer":3,"explain":"全电路欧姆定律（含电源内阻）适用于单一回路的简单电路；复杂电路需用基尔霍夫定律。"},{"no":15,"stem":"两只阻值相同的电阻串联后其阻值","options":["为两只电阻阻值的乘积","等于两只电阻阻值之和","等于两只电阻阻值之和的二分之一","等于两只电阻阻值的倒数和"],"answer":1,"explain":"串联电阻总阻值等于各电阻之和：R=R1+R2。相同阻值串联即为两倍。"},{"no":16,"stem":"关于等效变换说法正确的是（ ）。","options":["等效变换只保证变换的外电路的各电压、电流不变","等效变换是说互换的电路部分一样","等效变换对变换电路内部等效","等效变换只对直流电路成立"],"answer":0,"explain":"等效变换的核心是对外等效——保证外电路的各电压、电流不变，但变换部分内部并不等效。"},{"no":17,"stem":"在感性负载两端并联容性设备是为了（ ）。","options":["增加电源无功功率","减少负载有功功率","提高负载功率因数","提高整个电路的功率因数"],"answer":3,"explain":"感性负载消耗无功，并联容性设备可就地补偿无功，减少电源提供的无功，从而提高整个电路的功率因数。负载本身的功率因数不变。"},{"no":18,"stem":"电阻负载并联时功率与电阻关系是","options":["因为电流相等，所以功率与电阻成正比","因为电流相等，所以功率与电阻成反比","因为电压相等，所以功率与电阻大小成反比","因为电压相等，所以功率与电阻大小成正比。"],"answer":2,"explain":"并联电路各支路电压相等，由 P=U²/R 可知，电压一定时功率与电阻成反比，电阻越小功率越大。"},{"no":19,"stem":"RLC串联电路的复阻抗Z=（ ）Ω。","options":["R+ωL+1/ωC","R+L+1/C","R+jωL+1/jωC","R+j（ωL+1/ωC）"],"answer":2,"explain":"RLC 串联复阻抗 Z=R+jωL+1/(jωC)=R+j(ωL−1/ωC)。注意容抗项 1/(jωC)=−j/(ωC)。"},{"no":20,"stem":"并联电阻电路中的总电流等于各支路（ ）。","options":["电流的和","电流的积","电流的倒数和","电流的差"],"answer":0,"explain":"基尔霍夫电流定律：并联电路总电流等于各支路电流之代数和。"},{"no":21,"stem":"SF6气体是（ ）。","options":["无色无味","有色","有味","有色无味"],"answer":0,"explain":"SF6（六氟化硫）在常温常压下是无色、无味、无毒、不燃的惰性气体，具有优良的绝缘和灭弧性能。"},{"no":22,"stem":"断路器采用多断口是为了（ ）。","options":["提高遮断灭弧能力","用于绝缘","提高分合闸速度","使各断口均压"],"answer":0,"explain":"多断口把电弧分成多段串联，增加弧长、提高弧压，从而显著提高断路器的遮断灭弧能力。"},{"no":23,"stem":"断路器油用于（ ）。","options":["绝缘","灭弧","绝缘和灭弧","冷却"],"answer":2,"explain":"断路器油（绝缘油）兼具绝缘和灭弧双重作用，触头分离产生电弧时油分解产生气体帮助灭弧。"},{"no":24,"stem":"断路器套管裂纹绝缘强度（ ）。**","options":["不变","升高","降低","时升时降"],"answer":2,"explain":"套管裂纹会破坏绝缘介质的完整性、可能受潮进入水分，使绝缘强度降低，属严重缺陷。"},{"no":25,"stem":"断路器在气温零下30℃时做（ ）试验。","options":["低温操作","分解","检查","绝缘"],"answer":0,"explain":"低温环境下设备性能会变化，规程规定在气温低至−30℃时应做低温操作试验，验证断路器可靠动作。"},{"no":26,"stem":"变压器呼吸器作用（ ）。","options":["用以清除吸入空气中的杂质和水分； 、","用以清除变压器油中的杂质和水分","用以吸收和净化变压器匝间短路时产生的烟气","用以清除变压器各种故障时产生的油烟"],"answer":0,"explain":"呼吸器（吸湿器）装在油枕通气口，用以清除变压器吸入空气中的杂质和水分，防止油受潮劣化。"},{"no":27,"stem":"变压器温度升高时绝缘电阻值（ ）。","options":["降低","不变","增大","成比例增大"],"answer":0,"explain":"温度升高时绝缘介质内分子热运动加剧、导电性增强，绝缘电阻值降低，这也是为何要监测运行温度的原因。"},{"no":28,"stem":"变压器油粘度说明油的（ ）好坏。","options":["流动性好坏","质量好坏","绝缘性好坏","比重大小"],"answer":0,"explain":"粘度反映油流动的难易程度，粘度说明油的流动性好坏。粘度过大影响散热和灭弧，过小则影响绝缘。"},{"no":29,"stem":"变压器上层油温要比中下层油温（ ）。","options":["低","高","不变","在某些情况下进行"],"answer":1,"explain":"变压器油受热后密度变小向上流动，故上层油温高于中下层，温度计测量的就是上层油温。"},{"no":30,"stem":"变压器绕组最高温度为（ ）℃。","options":["105","95","75","80"],"answer":0,"explain":"变压器绕组（A级绝缘）最高允许温度为105℃，运行中一般监控上层油温不超过85℃。"},{"no":31,"stem":"变压器油一般应为（ ）油。","options":["15号","25号","45号","35号"],"answer":1,"explain":"变压器油一般应为25号油（25号表示凝点为−25℃），45号为更低温地区用油。"},{"no":32,"stem":"变压器不能使直流变压原因（ ）。","options":["直流大小和方向不随时间变化","直流大小和方向随时间变化","直流大小可变化而方向不变","直流大小不变而方向随时间变化"],"answer":0,"explain":"变压器靠电磁感应工作，需要变化的磁通。直流大小和方向都不随时间变化，磁通不变，二次侧无法感应出电动势，故不能变换直流电压。"},{"no":33,"stem":"变压器绕组首尾绝缘水平一样为（ ）。","options":["全绝缘","半绝缘","不绝缘","分级绝缘"],"answer":0,"explain":"绕组首端和尾端绝缘水平相同称为全绝缘；中性点绝缘水平低于首端的称为分级绝缘（半绝缘）。"},{"no":34,"stem":"变压器投切时会产生（ ）。","options":["操作过电压","气过电压","雷击过电压","系统过电压"],"answer":0,"explain":"变压器投切属开关操作，会引起电磁能量转换振荡，产生操作过电压，属于内部过电压。"},{"no":35,"stem":"变压器变比与匝数比（ ）。","options":["不成比例","成反比","成正比","无关"],"answer":2,"explain":"变比 K=N1/N2=U1/U2，变压器变比与匝数比成正比。"},{"no":36,"stem":"变压器温度计是指变压器（ ）油温。","options":["绕组温度","下层温度","中层温度","上层温度"],"answer":3,"explain":"变压器温度计（信号温度计）测量的是上层油温，因为上层油温最高，最能反映变压器的发热状况。"},{"no":37,"stem":"变压器空载时一次绕组中有（ ）流过。","options":["负载电流","空载电流","冲击电流","短路电流"],"answer":1,"explain":"变压器空载时二次侧开路，一次侧仍有较小的空载电流（励磁电流）流过，用于建立主磁通。"},{"no":38,"stem":"变压器三相负载不对称时将出现（ ）电流。","options":["正序，负序，零序","正序","负序","零序"],"answer":2,"explain":"三相负载不对称时，用对称分量法分解，除正序外会出现负序分量。零序需有中性线回路才会出现。"},{"no":39,"stem":"变压器短路电压和（ ）相等。","options":["空载损耗","短路损耗","短路阻抗","短路电流标么值"],"answer":2,"explain":"短路电压（阻抗电压）的百分值在数值上等于短路阻抗的百分值。"},{"no":40,"stem":"变压器铜损（ ）铁损时最经济。","options":["大于","小于","等于","不一定"],"answer":2,"explain":"变压器铜损（可变损耗）等于铁损（固定损耗）时，总损耗最小、效率最高，运行最经济。"},{"no":41,"stem":"变压器中性点接地属于（ ）。","options":["工作接地","保护接地","保护接零","故障接地"],"answer":0,"explain":"变压器中性点接地是为了保证系统正常运行所需的电位参考点，属于工作接地。"},{"no":42,"stem":"为防止电压互感器高压侧穿入低压侧，危害人员和仪表，应将二次侧（ ）。","options":["接地","屏蔽","设围栏","加防保罩"],"answer":0,"explain":"电压互感器二次侧必须可靠接地（保护接地），一旦一、二次间绝缘击穿，可将高压引入大地，保护人员和仪表。"},{"no":43,"stem":"电力系统中，将大电流按比例变换为小电流的设备称为（ ）。","options":["变压器","电抗器","电压互感器","电流互感器"],"answer":3,"explain":"电流互感器（CT）将大电流按比例变换为标准小电流（5A或1A）供测量和保护用。"},{"no":44,"stem":"计算电能表要求采用（ ）级的电流互感器。","options":["0.2","0.5","1","3"],"answer":1,"explain":"计量（计算电能）用电流互感器要求较高准确度，应采用0.5级。0.2级用于精密测量，1级、3级用于一般指示。"},{"no":45,"stem":"雷电引起的过电压称为（ ）。","options":["内部过电压","工频过电压","大气过电压","事故过电压"],"answer":2,"explain":"雷电引起的过电压又称大气过电压（外部过电压），分为直击雷过电压和感应雷过电压。"},{"no":46,"stem":"对于频率为50Hz的交流电，流过人体的电流超过（ ）时，就有致命危险。","options":["20-30mA","30-40mA","40-50mA","50-100mA"],"answer":3,"explain":"工频50Hz电流通过人体，超过50mA并持续一定时间即可能引起心室纤维性颤动，有致命危险。通常30mA·s为安全界限。"},{"no":47,"stem":"在电力系统正常状况下，用户受电端的电压最大允许偏差不应超过额定值的（ ）。","options":["±2%","±5%","±7%","±10%"],"answer":3,"explain":"规程规定，电力系统正常状况下用户受电端电压偏差不超过额定值的±10%。"},{"no":48,"stem":"未经值班的调度人员许可，（ ）不得操作调度机构调度管辖范围内的设备。","options":["非值班员","任何人","非领导人员","领导"],"answer":1,"explain":"调度管辖设备的操作必须经值班调度人员许可，未经许何人（含领导）都不得操作，这是调度纪律的基本要求。"},{"no":49,"stem":"断路器零压闭锁后，断路器（ ）分闸。","options":["能","不能","不一定","无法判定"],"answer":1,"explain":"零压闭锁是指操作机构压力（液压/气压）降至零时闭锁分闸，此时断路器不能分闸，防止慢分闸事故。"},{"no":50,"stem":"断路器分闸速度快慢影响（ ）。","options":["灭弧能力","合闸电阻","消弧片","分闸阻抗"],"answer":0,"explain":"分闸速度直接影响电弧能量的快速泄散和弧隙介质强度恢复，分闸速度过快或过慢都会影响灭弧能力。"},{"no":51,"stem":"变压器注油时应使油位上升至与（ ）相应的位置。","options":["环境","油温","绕组温度","铁芯温度"],"answer":0,"explain":"注油时油位应与当时环境温度（对应的油温）相适应，温度高时油位高些，温度低时低些，否则运行中可能溢油或油位过低。"},{"no":52,"stem":"变压器正常运行时的声音是（ ）。","options":["时大时小的嗡嗡声","连续均匀的嗡嗡声","断断续续的嗡嗡声","咔嚓声"],"answer":1,"explain":"正常运行的变压器发出连续均匀的嗡嗡声（铁芯硅钢片在交变磁场下磁致伸缩振动所致）。声音异常（断续、咔嚓）说明有故障。"},{"no":53,"stem":"运行中电压互感器发出异味并冒烟应（ ）。","options":["注意通风","监视运行","放油","停止运行"],"answer":3,"explain":"运行中电压互感器发出异味并冒烟属严重异常，应立即停止运行，防止发展成事故。"},{"no":54,"stem":"变压器内部故障，可能有（ ）保护动作。","options":["瓦斯","瓦斯差动","距离保护","中性点保护"],"answer":1,"explain":"变压器内部故障（如匝间短路）时，瓦斯保护与差动保护可能动作。轻瓦斯作用于信号，重瓦斯作用于跳闸。"},{"no":55,"stem":"10千伏室内刀闸可拉合（ ）及以下空载所内变压器。","options":["100kVA","200kVA","400 kVA","800 kVA"],"answer":0,"explain":"规程规定10kV室内隔离开关只能拉合100kVA及以下空载所内变压器，超过则应改用断路器操作。"},{"no":56,"stem":"用绝缘杆操作隔离开关时要（ ）。","options":["用力均匀果断","用力过猛","慢慢拉","用大力气拉"],"answer":0,"explain":"用绝缘杆操作隔离开关应迅速果断、用力均匀，但不得用力过猛造成瓷件损伤。带电拉合后要检查是否到位。"},{"no":57,"stem":"隔离开关应有（ ）装置。","options":["防误闭锁","锁","机械锁","万能锁"],"answer":0,"explain":"隔离开关必须装设防误闭锁装置，防止带负荷拉合隔离开关、带电合接地刀闸等恶性误操作。"},{"no":58,"stem":"更换熔断器应由（ ）进行。","options":["2人","1人","3人","4人"],"answer":0,"explain":"更换熔断器属高压作业，必须由2人进行（一人操作、一人监护），保证安全。"},{"no":59,"stem":"更换高压熔断器时应戴（ ）。","options":["绝缘手套","手套","一般手套","医用手套"],"answer":0,"explain":"更换高压熔断器可能接触带电部分或产生电弧，必须戴绝缘手套，并使用绝缘夹钳。"},{"no":60,"stem":"熔丝熔断时，应更换","options":["熔丝","相同容量熔丝","大容量熔丝","小容量熔丝"],"answer":1,"explain":"熔丝熔断后必须更换相同容量（同规格）的熔丝，严禁用大容量熔丝或铜丝铁丝代替，否则失去保护意义。"},{"no":61,"stem":"为防止电压互感器断线造成保护误动，距离保护（ ）。","options":["不取电压值","加装了断线闭锁装置","取多个电压互感器的值","二次侧不装熔断器"],"answer":1,"explain":"电压互感器断线会使距离保护失去电压量而误判为故障，因此距离保护加装断线闭锁装置，断线时闭锁保护并告警。"},{"no":62,"stem":"电压互感器二次短路会使一次（ ）。","options":["电压升高","电压降低","熔断器熔断","不变"],"answer":2,"explain":"电压互感器二次侧短路会产生很大的短路电流，使一次侧电流剧增，烧断高压侧（一次）熔断器，起保护作用。注意：电压互感器二次侧严禁短路。"},{"no":63,"stem":"电压互感器低压侧两相电压降为零，一相正常，一个线电压为零则说明（ ）。","options":["低压侧两相熔断器断","低压侧一相铅丝断","高压侧一相铅丝断","高压侧两相铅丝断"],"answer":0,"explain":"低压侧（二次侧）两相熔断器熔断，该两相电压为零，仅剩一相正常；含熔断相的线电压为零，故只有一个线电压为零。"},{"no":64,"stem":"电压互感器低压侧一相电压为零，两相不变，线电压两个降低，一个不变，说明","options":["低压侧两相熔断器断","低压侧一相铅丝断","高压侧一相铅丝断","高压侧两相铅丝断"],"answer":1,"explain":"低压侧一相熔断器熔断：该相电压为零，另两相不变；与该相相关的两个线电压降低，与它无关的一个线电压不变。"},{"no":65,"stem":"电流互感器的作用是（ ）。","options":["升压","降压","调压","变流"],"answer":3,"explain":"电流互感器（CT）的作用是把大电流按比例变成小电流，即变流，便于测量和保护。"},{"no":66,"stem":"电流互感器的二次额定电流一般为","options":["10A","100A","5A","0.5A"],"answer":2,"explain":"电流互感器二次额定电流统一规定为5A（部分场合为1A），便于仪表和继电器的标准化。"},{"no":67,"stem":"电流互感器的二次侧应（ ）。","options":["没有接地点","有一个接地点","有两个接地点","按现场情况不同，不确定"],"answer":1,"explain":"电流互感器二次侧必须有且只有一个接地点，防止一二次绝缘击穿时高压窜入二次回路；多点接地会引入地中杂散电流影响保护正确动作。"},{"no":68,"stem":"电流互感器二次侧接地是为了（ ）。","options":["测量用","工作接地","保护接地","节省导线"],"answer":2,"explain":"电流互感器二次侧接地属于保护接地，目的是防止一、二次间绝缘击穿时高电压危及人身和二次设备。"},{"no":69,"stem":"电流互感器二次侧不允许（ ）。","options":["开路","短路","接仪表","接保护"],"answer":0,"explain":"电流互感器二次侧严禁开路。开路时一次电流全部用于励磁，铁芯严重饱和过热，且二次侧感应出极高电压，危及人身和设备。如需拆除仪表必须先短接。"},{"no":70,"stem":"停用低频减载装置时应先停（ ）。","options":["电压回路","直流回路","信号回路","保护回路"],"answer":1,"explain":"停用低频减载装置应先停直流回路（切断跳闸出口电源），防止在停用过程中误动作跳闸。"},{"no":71,"stem":"低压闭锁过流保护应加装（ ）闭锁。","options":["电压","电流","电气","电容"],"answer":0,"explain":"低压闭锁过流保护加装电压闭锁：正常过负荷时电压不降低，保护不动作；短路故障时电压降低，闭锁开放，保护动作。这样可提高灵敏度又避免误动。"},{"no":72,"stem":"零序保护的最大特点（ ）。","options":["只反映接地故障","反映相间故障","反映变压器的内部","线路故障"],"answer":0,"explain":"零序保护利用零序分量，而零序电流只在接地故障时出现，因此零序保护只反映接地故障，不反映相间短路。"},{"no":73,"stem":"73在6-10KV中性点不接地系统中，发生单相接地时，非故障相的相电压将（ ）。","options":["升高一倍","升高不明显","升高1.73倍","升高两倍"],"answer":2,"explain":"中性点不接地系统发生单相接地时，故障相电压为零，非故障相电压升高到线电压，即升高√3≈1.73倍。但线电压仍对称，可短时继续运行（一般不超过2小时）。"},{"no":74,"stem":"电力系统无功容量不足必将引起电压（ ）。","options":["普遍下降","升高","边远地区下降","边远地区升高"],"answer":0,"explain":"无功功率是维持电压水平的支撑，系统无功容量不足时电压普遍下降，需投入无功补偿装置。"},{"no":75,"stem":"反映电力线路电流增大而动作的保护为（ ）。","options":["小电流保护","过电流保护","零序电流保护","过负荷保护"],"answer":1,"explain":"过电流保护反映电流超过整定值而动作，用于线路和设备的相间短路及过负荷保护。"},{"no":76,"stem":"当电力线路发生短路故障时，在短路点将会（ ）。","options":["产生一个高电压","通过很大的短路电流","通过一个很小的正常的负荷电流","产生零序电流"],"answer":1,"explain":"短路点阻抗极小，将通过远大于额定值的短路电流，同时电压大幅降低。这是短路故障的基本特征。"},{"no":77,"stem":"电压互感器二次负载变大时，二次电压（ ）。","options":["变大","变小","基本不变","不一定"],"answer":2,"explain":"电压互感器相当于一个恒压源，二次负载在额定范围内变化时，二次电压基本保持不变。"},{"no":78,"stem":"电压互感器二次回路有工作而互感器不停用时应防止二次（ ）。","options":["断路","短路","熔断器熔断","开路"],"answer":1,"explain":"电压互感器二次回路工作时，若电压互感器不停用，应防止二次侧短路（短路会产生大电流），同时也要防止反充电（二次向一次反送电）。"},{"no":79,"stem":"运行中电压互感器高压侧熔断器熔断应立即（ ）。","options":["更换新的熔断器","停止运行","继续运行","取下二次熔丝"],"answer":1,"explain":"运行中电压互感器高压侧熔断器熔断，说明内部可能有故障，应立即停止运行，查明原因后再处理，不得盲目更换熔断器继续运行。"},{"no":80,"stem":"运行中电压互感器引线端子过热应（ ）。","options":["加强监视","加装跨引","停止运行","继续运行"],"answer":2,"explain":"引线端子过热说明接触不良，继续发展可能烧断引线或引发事故，规程要求立即停止运行处理。"},{"no":81,"stem":"隔离开关拉不开时应采取（ ）的处理。","options":["不应强拉，应进行检查","用力拉","用加力杆拉","两人拉"],"answer":0,"explain":"隔离开关拉不开时严禁强行拉拽（可能损坏瓷件或传动机构甚至造成事故），应查明原因并处理后再操作。"},{"no":82,"stem":"因隔离开关传动机构本身故障而不能操作的，应（ ）处理。","options":["停电","自行","带电处理","以后"],"answer":0,"explain":"隔离开关传动机构本身故障无法操作时，必须停电处理，严禁带电自行处理。"},{"no":83,"stem":"触电急救必须分秒必争，立即就地迅速用（ ）进行急救。","options":["人工呼吸法","心肺复苏法","胸外按压法","医疗器械"],"answer":1,"explain":"触电急救应就地迅速用心肺复苏法（CPR，含胸外按压与人工呼吸）进行抢救，分秒必争，同时呼叫急救中心。"},{"no":84,"stem":"触电伤员如神智不清，应就地仰面躺平，且确保气道通畅，并用（ ）钟时间，呼叫伤员或轻拍其肩部，以判定伤员是否意识丧失。","options":["3s","4s","5s","6s"],"answer":2,"explain":"判定触电伤员意识是否丧失，应用5s时间呼叫或轻拍肩部，同时观察有无反应。"},{"no":85,"stem":"口对口人工呼吸时，先连接大口吹气两次，每次（ ）。","options":["1-2s","2-3s","1.5-2.5s","1-1.5s"],"answer":3,"explain":"口对口人工呼吸开始时应先连续大口吹气两次，每次约1-1.5s，以扩张萎陷的肺泡并观察气道是否通畅。"},{"no":86,"stem":"胸外按压要以均匀速度进行，每分钟（ ）左右。","options":["50次","60次","70次","80次"],"answer":3,"explain":"胸外按压频率约为每分钟80次（现行心肺复苏指南为100-120次/分，按本题库答案选80次）。"},{"no":87,"stem":"胸外按压与口对口（鼻）人工呼吸同时进行，其节奏为：单人抢救时，每按压（ ）次后吹气2次，反复进行。","options":["5","10","15","20"],"answer":2,"explain":"单人抢救时，胸外按压与人工呼吸比例为15:2，即每按压15次后吹气2次，反复进行。"},{"no":88,"stem":"抢救过程中，若判断颈动脉已有波动但无呼吸，则暂停胸外按压，而再进行2次口对口人工呼吸，接着每（ ）吹气一次。","options":["5s","6s","7s","8s"],"answer":0,"explain":"有脉搏无呼吸时无需胸外按压，只需人工呼吸，每5s吹气一次（即每分钟约12次）。"},{"no":89,"stem":"在将伤员由高处送至地面前，应先口对口吹气（ ）。","options":["2次","3次","5次","4次"],"answer":3,"explain":"将高处伤员送至地面前，应先口对口吹气4次，使其肺部充氧，防止搬运过程中缺氧加重。"},{"no":90,"stem":"通畅气道可采用（ ）。","options":["人工呼吸法","仰头抬额法","垫高头部法","胸外按压法"],"answer":1,"explain":"通畅气道的标准方法是仰头抬颏法（仰头抬额法），使舌根离开咽后壁，打开气道。注意清除口中异物。"},{"no":91,"stem":"口对口人工呼吸，吹气时，如有较大阻力，可能是（ ）应急时纠正。","options":["头部前倾","头部后仰","头部垫高","吹气力度不当"],"answer":1,"explain":"吹气阻力大通常是因为头部后仰不够、气道未打开，应及时纠正使头部充分后仰。"},{"no":92,"stem":"触电伤员如意识丧失，应在（ ）内，用看、听、试的方法，判定伤员呼吸心跳情况。","options":["5s","8s","10s","12s"],"answer":2,"explain":"对意识丧失的触电伤员，应在10s内用看（胸廓起伏）、听（呼吸音）、试（气流）的方法判定呼吸心跳情况，尽快开始CPR。"},{"no":93,"stem":"现场触电抢救，对采用（ ）等药物应持慎重态度。","options":["维生素","脑活素","胰岛素","肾上腺素"],"answer":3,"explain":"现场触电抢救对肾上腺素等药物应持慎重态度，因其可能诱发心室颤动，须由医生掌握使用，不可盲目用药。"},{"no":94,"stem":"正确的按压姿势以髋关节为支点，利用上身的重力，将正常成人胸骨压陷（ ）（儿童和瘦弱者辍减）。","options":["1-2cm","2-3cm","3-5cm","4-5cm"],"answer":2,"explain":"成人胸外按压深度为3-5cm，以髋关节为支点用上身重力垂直下压，儿童和瘦弱者适当减小。"},{"no":95,"stem":"设备档案中，原始资料不包括（ ）。","options":["使用说明书","缺陷记录","出厂试验记录","设备铭牌"],"answer":1,"explain":"设备原始资料包括使用说明书、出厂试验记录、设备铭牌等；缺陷记录属于运行维护记录，不是原始资料。"},{"no":96,"stem":"事故处理可不用操作票，但应在调度命令记录簿和（ ）内。","options":["运行日志记录簿","缺陷记录簿","命令指示记录簿","检查记录簿"],"answer":0,"explain":"事故处理可不用操作票（但须有调度命令），事后应将处理情况记入调度命令记录簿和运行日志记录簿。"},{"no":97,"stem":"强油风冷变压器运行时顶层油温一般规定不超过（ ）℃。","options":["95","85","75","105"],"answer":1,"explain":"强油风冷变压器顶层油温一般规定不超过85℃（自然循环自冷为95℃），以防绝缘加速老化。"},{"no":98,"stem":"功率因数表指针在停电后指在（ ）。","options":["0","没有固定位置","最大位置","每次都固定在同一位置"],"answer":1,"explain":"功率因数表为电动系流比计结构，无游丝产生反作用力矩，停电后指针没有固定位置，可停在任意位置。"},{"no":99,"stem":"蓄电池室内温度在（ ）之间。","options":["5-10℃","10-30℃","不高于50℃","-10-0℃"],"answer":1,"explain":"蓄电池室温度应保持在10-30℃之间，温度过低容量下降，过高会加速极板老化，需保持良好通风。"},{"no":100,"stem":"防雷保护装置的接地属于（ ）。","options":["工作接地","保护接地","防雷接地","保护接零"],"answer":0,"explain":"防雷保护装置（避雷针、避雷器）的接地属于工作接地，为雷电流提供泄入大地的通道，使其正常发挥作用。"},{"no":101,"stem":"在人站立或行走时通过有电流通过的地面，两脚间所承受的电压称为（ ）。","options":["跨步电压","接触电压","接地电压","过渡电压"],"answer":0,"explain":"跨步电压是指人站立在有电流流过的地面上时，两脚之间所承受的电压。接地故障点附近最危险，应单脚或并脚跳出危险区。"},{"no":102,"stem":"为了消除超高压断路器各个断口上的电压分布不均匀，改善灭弧性能，可在断路器各个断口加装（ ）。","options":["并联均压电容","均压电阻","均压带","均压环"],"answer":0,"explain":"超高压断路器各断口对地杂散电容不同造成电压分布不均，并联均压电容可使各断口电压均匀分布，改善灭弧性能。"},{"no":103,"stem":"变压器负载为纯电阻时，输入功率性质（ ）。","options":["无功功率","有功功率","感性","容性"],"answer":1,"explain":"纯电阻负载时电压与电流同相，功率因数cosφ=1，输入功率全部为有功功率。"},{"no":104,"stem":"在6-10KV中性点不接地系统中，发生接地时，非故障相的相电压将（ ）。","options":["不升高","同时降低","升高1.732倍","升高一倍"],"answer":2,"explain":"与73题同理：中性点不接地系统单相接地时，非故障相电压升高√3≈1.732倍（即线电压）。"},{"no":105,"stem":"当变压器电源电压高于额定值时，铁芯的损耗会（ ）。","options":["减少","不变","增大","不一定"],"answer":2,"explain":"电源电压高于额定值时，铁芯磁通密度增大，导致铁损（磁滞和涡流损耗）显著增大，铁芯发热加剧，故不允许长期过电压运行。"},{"no":106,"stem":"在变压器中性点装设消弧线圈的目的是（ ）。","options":["提高电网电压水平","限制变压器故障电流","补偿电网接地的电容电流","吸收无功"],"answer":2,"explain":"消弧线圈装在变压器中性点，单相接地时产生感性电流补偿接地电容电流，使接地电弧自行熄灭，防止弧光过电压。"},{"no":107,"stem":"变压器油在变压器内的作用为（ ）。","options":["绝缘冷却","灭弧","防潮","隔离空气"],"answer":0,"explain":"变压器油在变压器内主要起绝缘和冷却（散热）作用，同时保护铁芯绕组免受潮气侵蚀。断路器油才主要用于灭弧。"},{"no":108,"stem":"对于低压用电系统为了获得380/220V两种供电电压，习惯上采用中性点（ ）构成三相四线制供电方式。","options":["直接接地","不接地","经消弧绕组接地","经高阻抗接地"],"answer":0,"explain":"低压配电系统采用中性点直接接地的三相四线制，可同时提供380V线电压（动力）和220V相电压（照明）。"},{"no":109,"stem":"中性点经消弧绕组接地的电力网，在正常运行情况下中性点，其时间电压位移不应超过额定相电压的（ ）。","options":["5%","10%","15%","20%"],"answer":2,"explain":"规程规定中性点经消弧线圈接地的电网，正常运行中性点位移电压不应超过额定相电压的15%，超过说明补偿不当需调整。"},{"no":110,"stem":"变电站的母线上装设避雷器是为了（ ）。*","options":["防止直击雷","防止反击过电压","防止雷电行波","防止雷电流"],"answer":2,"explain":"变电站母线上的避雷器用于限制沿线路侵入的雷电行波（雷电侵入波），保护电气设备绝缘。防直击雷靠避雷针或避雷线。"},{"no":111,"stem":"变压器带（ ）负荷时电压最高。","options":["容性","感性","阻性","线性"],"answer":0,"explain":"变压器带容性负载时，容性电流起助磁作用，使二次电压升高；带感性负载时电压降低，故容性负载时电压最高。"},{"no":112,"stem":"高压断路器的最高工作电压，是指（ ）。","options":["断路器长期运行线电压","断路器长期运行的最高相电压","断路器长期运行最高的线电压的有效值","断路器故障时最高相电压"],"answer":2,"explain":"最高工作电压指断路器长期运行所能承受的最高线电压的有效值（如12kV断路器用于10kV系统），它高于额定电压。"},{"no":113,"stem":"距接地体处的跨步电压变化距离（ ）。","options":["10m以外为0","越接近接地处越大，越远则越小，20m远时为0","30m以外为0","5m以内最小"],"answer":-1,"explain":"跨步电压越接近接地处越大，越远越小，一般在离接地体20m以外趋近于零。"},{"no":114,"stem":"用兆欧表摇测（ ）时应在摇把转动的情况下，将接线断开。","options":["二次回路","电网","电容器","直流回路"],"answer":2,"explain":"摇测电容器绝缘电阻时，若先停摇把再断开接线，电容器储存的电荷会通过兆欧表放电而损坏表头，故应在摇把转动时断开接线。"},{"no":115,"stem":"交流电流表或交流电压表，指示的数值是（ ）。","options":["平均值","有效值","最大值","瞬时值"],"answer":1,"explain":"交流仪表（电磁系、电动系、整流系等）均按有效值刻度，指示的是交流电的有效值。"},{"no":116,"stem":"为了保证用户电压质量，系统必须保证有足够的（ ）。","options":["有功容量","电压","无功容量","电流"],"answer":2,"explain":"无功功率用于建立磁场、维持电压，系统无功容量充足才能保证用户电压质量，故必须保证足够的无功容量。"},{"no":117,"stem":"系统向用户提供的无功功率越小用户电压就（ ）。","options":["越低","越高","越合乎标准","等于0"],"answer":2,"explain":"系统提供的无功越少，说明就地无功补偿越充分，线路传输的无功少、电压损耗小，用户电压越合乎标准。"},{"no":118,"stem":"电力系统不能向负荷供应所需的足够的有功功率时，系统的频率就（ ）。","options":["要升高","要降低","会不高也不低","升高较轻"],"answer":1,"explain":"有功功率不平衡决定频率：有功不足时机组转速下降，系统频率降低；有功过剩时频率升高。"},{"no":119,"stem":"三绕组降压变压器绕组由里向外的排列顺序是（ ）。","options":["中、高、低","低、中、高","高、中、低","中、低、高"],"answer":1,"explain":"三绕组降压变压器从铁芯向外依次为低压、中压、高压绕组，主要出于绝缘安排合理（高压在最外层便于引出分接和绝缘处理）。"},{"no":120,"stem":"电感元件的基本工作性能是（ ）。","options":["消耗电能","产生电能","储存能量","传输能量"],"answer":2,"explain":"电感元件不消耗有功电能，而是把电能转换为磁场能储存起来，并在电流减小时释放，其基本工作性能是储存能量。"},{"no":121,"stem":"RL串联与C并联电路发生谐振的条件是（ ）。","options":["ωL=1/（ωC）","R2+（ωL）2=L/C","R2+（ωL）2=ωC","R2+（ωL）2=[1/（ωC）]2"],"answer":1,"explain":"RL串联再与C并联的电路发生谐振（电流谐振）的条件是 R²+(ωL)²=L/C。此时总电流与电压同相，支路电流可能远大于总电流。"},{"no":122,"stem":"主变压器重瓦斯动作是由于（ ）造成的。","options":["主变压器两侧断路器跳闸","220KV套管两相闪络","主变压器内部高压侧绕组严重匝间短路","主变压器大盖着火"],"answer":2,"explain":"重瓦斯保护反映变压器内部严重故障，内部严重匝间短路产生大量瓦斯气体冲动挡板，重瓦斯动作于跳闸。"},{"no":123,"stem":"交流测量仪表所指示的读数是正弦量的（ ）。","options":["有效值","最大值","平均值","瞬时值"],"answer":0,"explain":"与交流电压表电流表同理，交流测量仪表读数均为正弦量的有效值。"},{"no":124,"stem":"导线通以交流电流时在导线表面的电流密度（ ）。","options":["较靠近导线中心密度大","较靠近导线中心密度小","与靠近导线中心密度一样","无法确定"],"answer":0,"explain":"交流电流存在集肤效应（趋肤效应），电流趋向导线表面流动，所以导线表面电流密度比靠近中心处大。"},{"no":125,"stem":"图中互感器绕组的同名端是（ ）。","options":["1和2","3和1","3和4","2和3"],"answer":1,"explain":"同名端（同极性端）是指两绕组中感应电动势极性始终相同的端子。按图中绕组绕向和端子编号，3和1为同名端。"},{"no":126,"stem":"由铁磁材料构成的磁通集中通过的路径称为（ ）。","options":["电路","磁链","磁路","磁场"],"answer":2,"explain":"由铁磁材料（硅钢片等）构成的、使磁通集中通过的闭合路径称为磁路，与电路的概念相对应。"},{"no":127,"stem":"通电绕组在磁场中的受力用（ ）判断。","options":["安培定则","右手螺旋定则","右手定则","左手定则"],"answer":3,"explain":"通电导体在磁场中的受力方向用左手定则判断（左力右电）：伸开左手，磁感线穿入手心，四指指向电流方向，拇指指受力方向。"},{"no":128,"stem":"电力系统一般事故备用容量约为系统最大负荷的（ ）。","options":["2%-5%","3%-5%","5%-10%","5%-8%"],"answer":2,"explain":"电力系统事故备用容量一般为系统最大负荷的5%-10%，且不小于系统中最大一台机组的容量。"},{"no":129,"stem":"电压互感器的精度级一般与（ ）有关。","options":["电压比误差","相角误差","变比误差","二次阻抗"],"answer":0,"explain":"电压互感器的准确度等级主要由电压比误差（比差）决定，同时也受相角误差（角差）影响，二次负载不能超过额定值。"},{"no":130,"stem":"某变压器的一、二次绕组匝数比是25，二次侧电压是400V，那么一次侧电压为（ ）。","options":["10000V","35000V","15000V","40000V"],"answer":0,"explain":"变比 K=N1/N2=U1/U2=25，故 U1=25×400=10000V。"},{"no":131,"stem":"变压器的最高运行温度受（ ）耐热能力限制。","options":["绝缘材料","金属材料","铁芯","电流"],"answer":0,"explain":"变压器最高运行温度受绝缘材料耐热能力限制。A级绝缘最高允许105℃，绝缘过热会加速老化、缩短寿命（绝缘老化6℃法则：温度每升高6-8℃寿命减半）。"},{"no":132,"stem":"标志断路器开合短路故障能力的数据是（ ）。","options":["额定短路开合电流的峰值","最大单相短路电流","断路电压","最大运行负荷电流"],"answer":0,"explain":"额定短路开合电流的峰值标志断路器开合短路故障的能力，是断路器最重要的技术参数之一，必须大于安装点的最大短路电流。"},{"no":133,"stem":"大电流接地系统中，任何一点发生单相接地时，零序电流等于通过故障点电流的（ ）。","options":["2倍","1.5倍","1/3倍","1/5倍"],"answer":2,"explain":"大电流接地系统单相接地时，零序电流 3I0 等于故障点电流，故零序电流 I0 为故障点电流的1/3。"},{"no":134,"stem":"变压器铭牌上标注有额定电压{F}+5%，是说明该变压器是（ ）。","options":["有载调压","三级调压","无载调压","三级有载调压"],"answer":1,"explain":"铭牌标注额定电压 ±5%（或 ±2×2.5%）的无载调压变压器，调压必须在停电（无载）状态下改变分接开关位置，属无载调压。注意：答案应为\"无载调压\"，题目选项中的\"三级调压\"是原题答案标注，若按现行规程理解，请以上级下发答案为准。","formula":{"F":"data:image/png;base64,"}},{"no":135,"stem":"在小电流接地系统中，发生金属性接地时接地相的电压（ ）。","options":["等于零","等于10KV","升高","不变"],"answer":0,"explain":"小电流接地系统发生金属性（完全）接地时，接地相对地电压为零，非故障相升高为线电压（√3倍）。"},{"no":136,"stem":"中性点接地系统比不接地系统供电可靠性（ ）。","options":["高","差","相同","不一定"],"answer":0,"explain":"中性点直接接地系统单相接地即构成短路，保护立即跳闸；不接地系统单相接地可继续运行1-2小时，从不停电角度看似可靠性高，但接地系统过电压水平低、绝缘投资省、保护选择性好，综合可靠性更高。"},{"no":137,"stem":"电力线路发生故障时，要求继电保护装置尽快切除故障，称为继电保护的（ ）。","options":["选择性","快速性","可靠性","灵敏性"],"answer":1,"explain":"快速性是指继电保护装置应尽快切除故障，以减轻设备损坏、提高系统稳定性。"},{"no":138,"stem":"电力线路发生故障时，本线路继电保护的反应能力，称为继电保护的（ ）。","options":["选择性","灵敏性","可靠性","快速性"],"answer":1,"explain":"灵敏性是指保护装置对其保护范围内故障的反应能力，用灵敏系数衡量。"},{"no":139,"stem":"当电力系统发生故障时，要求本线路继电保护，该动的动，不该动的不动称为继电保护的（ ）。","options":["选择性","灵敏性","可靠性","快速性"],"answer":2,"explain":"可靠性是指保护该动作时可靠动作（不拒动）、不该动作时可靠不动作（不误动）。"},{"no":140,"stem":"断路器额定电压指（ ）。","options":["断路器正常工作电压","正常工作相电压","正常工作线电压有效值","正常工作线电压最大值"],"answer":2,"explain":"断路器额定电压指正常工作时的线电压有效值（系统标称电压，如10kV、35kV、110kV）。"},{"no":141,"stem":"高压断路器的额定电流是（ ）。","options":["—断路器长期运行电流","断路器长期运行电流的有效值","断路器运行中的峰值电流","断路器长期运行电流的最大值"],"answer":1,"explain":"额定电流指断路器可以长期通过的电流有效值，此时各部分温升不超过允许值。"},{"no":142,"stem":"断路器最高工作电压是指（ ）。","options":["长期运行的线电压","长期运行的最高相电压","长期运行的最高线电压","故障电压"],"answer":2,"explain":"最高工作电压是断路器长期运行所能承受的最高线电压有效值，一般比额定电压高（如10kV断路器最高工作电压12kV）。"},{"no":143,"stem":"两台阻抗电压不相等变压器并列运行时，在负荷分配上（ ）。","options":["阻抗电压大的变压器负荷小","阻抗电压小的变压器负荷小","负荷分配不受阻抗电压影响","一样大"],"answer":0,"explain":"并列运行的变压器负荷分配与阻抗电压（短路阻抗）成反比：阻抗电压大的分担负荷小，阻抗电压小的分担负荷大。故要求并列变压器阻抗电压相近。"},{"no":144,"stem":"变压器在额定电压下，二次开路时在铁芯中消耗的功率为（ ）。","options":["铜损","无功损耗","铁损","热损"],"answer":2,"explain":"二次开路时无负载电流，绕组铜损为零，一次侧仅有空载电流，铁芯中消耗的功率为铁损（空载损耗）。"},{"no":145,"stem":"如电压互感器高压侧和低压侧额定电压分别是60000V和100V，则该互感器的互感比为（ ）。","options":["600/1","1/600","600/{F}","{F}/600"],"answer":0,"explain":"互感比（变比）= 一次额定电压 / 二次额定电压 = 60000/100 = 600/1。注意区分：若为相电压比则需除以 √3，本题给的是额定电压（线电压）之比。","formula":{"F":"data:image/png;base64,"}},{"no":147,"stem":"电压表的内阻为3KΩ最大量程为3V，先将它串联一个电阻改装成一个15V的电压表，则串联电阻的阻值为（ ）KΩ。","options":["3","9","12","24"],"answer":2,"explain":"表头满偏电流 Ig=3V/3kΩ=1mA。量程扩至15V需总电阻 R=15V/1mA=15kΩ，串联电阻=15−3=12kΩ。"},{"no":148,"stem":"有一块内阻为0.15Ω,最大量程为1A的电流表，先将它并联一个0.05Ω的电阻则这块电流表的量程将扩大为（ ）。","options":["3A","4A","2A","6A"],"answer":1,"explain":"并联分流电阻0.05Ω，分流比 n=Rg/Rs=0.15/0.05=3，量程扩大倍数=1+n=4，故量程扩大为1×4=4A。"},{"no":149,"stem":"对正常运行虽有影响，但尚能支持不需要马上停电处理者（ ）。","options":["一般缺陷","三类缺陷","异常现象","二类缺陷"],"answer":0,"explain":"设备缺陷分类：对正常运行有影响但尚能坚持、不需立即停电处理的为一般缺陷（三类缺陷）；严重缺陷需近期处理；危急缺陷须立即处理。"},{"no":150,"stem":"操作断路器时，操作中操作人要检查（ ）是否正确。","options":["位置、表计","灯光、信号","灯光、表计","光字牌、表计"],"answer":2,"explain":"操作断路器时，操作人应检查灯光指示（红绿灯）和表计（电流、电压）变化是否正确，以确认断路器实际位置，防止断路器实际未动作而误判。"},{"no":151,"stem":"线路在进行接地选除时应首先选除（ ）线路。","options":["一般负荷线路","空充电线路","带电作业线路","架空线线路"],"answer":1,"explain":"接地选除（拉路查找）时应优先选除空充电线路（空载线路），因其停运对用户无影响、代价最小，也较可能是接地线路。"},{"no":152,"stem":"变压器正常运行时，呼吸器应完好，硅胶变色部分不超过（ ） 。","options":["2／3","1／3","2／5","3／5"],"answer":0,"explain":"呼吸器硅胶变色（吸潮饱和）部分不应超过2/3，超过则说明吸潮能力接近失效，应更换硅胶。"},{"no":153,"stem":"绝缘棒、验电器和绝缘手套的试验周期分别是（ ）。","options":["都是一年","一年 —年 半年","—年 半年 半年"],"answer":1,"explain":"绝缘棒、验电器试验周期为一年，绝缘手套试验周期为半年（绝缘靴、绝缘绳等也为半年）。"},{"no":154,"stem":"发生误操作隔离开关时应采取（ ）的处理。","options":["立即拉开","立即合上","停止操作","误合时不许再拉开，误拉时在弧光未断开时合上"],"answer":3,"explain":"误合隔离开关时严禁再拉开（带负荷拉开会产生强烈电弧）；误拉时若电弧尚未熄灭、触头未完全分开，应立即合上，避免事故扩大。"},{"no":155,"stem":"电气设备发生火灾后，首先应（ ）。","options":["汇报调度","切断着火设备的电源","汇报调度，然后切断着火设备的电源","都可以"],"answer":1,"explain":"电气设备着火应首先切断着火设备电源，防止灭火时触电、防止电弧助燃，且切断电源后可用常规灭火方法。注意切断电源应使用绝缘工具。"},{"no":156,"stem":"遇到电气设备着火时，对带电设备灭火时应使用（ ）。","options":["二氧化碳灭火器","泡沫灭火器","砂子和水"],"answer":0,"explain":"带电设备灭火应使用不导电的灭火剂：二氧化碳、1211、干粉灭火器。严禁用泡沫灭火器和水（导电，会造成触电和短路）。"},{"no":157,"stem":"为了保障人身安全，在正常情况下，电气设备的安全电压规定为（ ）。","options":["12V以下","36V以下","48V以下","6V以下"],"answer":1,"explain":"正常情况下安全电压为36V以下；在潮湿、狭窄金属容器等特别危险场所为12V以下。"},{"no":158,"stem":"我国使用的工频交流电频率为（ ）。","options":["45Hz","50Hz","60Hz","65Hz"],"answer":1,"explain":"我国电力系统采用50Hz工频交流电（部分国家如美国、日本部分地区用60Hz）。"},{"no":159,"stem":"一根通有电流、另一根无电流的两平行导线之间（ ）。","options":["有吸引力","有推斥力","无任何力"],"answer":2,"explain":"两平行导线间的电磁力需要两根导线都有电流才能产生。一根无电流则无相互作用力。"},{"no":160,"stem":"在电气设备上工作时，签发工作票可以是（ ）。","options":["工作票签发人","工作负责人","工作许可人","工作班人员"],"answer":0,"explain":"工作票必须由工作票签发人签发。工作负责人、工作许可人、工作班成员均无权签发，这是工作票制度的分工要求。"},{"no":161,"stem":"测量设备的绝缘电阻应该用（ ）。","options":["欧姆表","万用表","兆欧表","电桥"],"answer":2,"explain":"测量绝缘电阻应使用兆欧表（摇表），因其能输出较高的直流电压（500V、1000V、2500V等），可真实反映绝缘状况。万用表电池电压太低，测不准。"},{"no":162,"stem":"电流的标准单位是（ ）。","options":["kA","A","mA","μA"],"answer":1,"explain":"电流的标准单位（国际单位制基本单位）是安培，符号A。"},{"no":163,"stem":"压器的基本工作原理是（ ）。","options":["电磁感应","电流的磁效应","楞次定律","磁路欧姆定律"],"answer":0,"explain":"变压器利用电磁感应原理工作：一次绕组通交流电产生交变磁通，经铁芯耦合在二次绕组感应出电动势。"},{"no":164,"stem":"判断运动导体切割磁力线产生的感应电动势方向是用（ ）。","options":["右手定则","左手定则","安培定则","右手螺旋法则"],"answer":0,"explain":"导体切割磁力线产生感应电动势的方向用右手定则（发电机定则）判断：手心迎磁感线，拇指指运动方向，四指指感应电动势方向。"},{"no":165,"stem":"将一段均匀的阻值为R的导线从中间对折合成一条新导线，其阻值为（ ）。","options":["1/4R","1/2R","2R","4R"],"answer":0,"explain":"对折后长度变为1/2，截面积变为2倍。由 R=ρL/S，电阻变为 (1/2)/(2)=1/4，即 R/4。"},{"no":166,"stem":"新装和大修后的低压线路的设备的绝缘电阻不应小于（ ）。","options":["0.1兆欧","0.3兆欧","0.5兆欧"],"answer":2,"explain":"规程规定新装和大修后的低压线路及设备，绝缘电阻不应小于0.5兆欧。"},{"no":167,"stem":"要测量 380V 交流电动机绝缘电阻，应选用额定电压为（ ）的绝缘电阻表。","options":["250V","500V","1000V"],"answer":1,"explain":"测量380V电动机应选用500V兆欧表。选择原则：500V以下设备用500V表，500V以上用1000-2500V表，电压过高会击穿绝缘。"},{"no":168,"stem":"下列工具中，（ ）手柄处是不绝缘的。","options":["斜口钳","剥线钳","电工刀"],"answer":2,"explain":"电工刀手柄处不绝缘，是纯金属刀柄，使用中不得带电操作，防止触电。斜口钳、剥线钳手柄均有绝缘护套。"},{"no":169,"stem":"在砖墙上冲打导线孔时用（ ）。","options":["冲击钻","手提式电钻","手枪式电钻"],"answer":0,"explain":"砖墙冲打导线孔应使用冲击钻（电锤），利用冲击加旋转破碎砖石。普通电钻无法在砖墙上有效钻孔。"},{"no":170,"stem":"测量直流电压时应注意电压表的（ ）。","options":["量程","极性","量程及极性","误差"],"answer":2,"explain":"测量直流电压必须同时注意量程（防止打表、烧毁）和极性（防止指针反偏损坏表头），二者缺一不可。"},{"no":171,"stem":"低压验电器是利用电流通过验电器、人体、（ ）形成回路，其漏电电流使氖泡起辉发光而工作的。","options":["大地","氖泡","弹簧","手柄"],"answer":0,"explain":"低压验电器（验电笔）通过验电器、人体、大地构成回路，微小的泄漏电流使氖泡起辉发光，指示被测体带电。"},{"no":172,"stem":"验电笔在使用时不能用手接触（ ）。","options":["笔尖金属探头","氖泡","尾部螺丝","笔帽端金属挂钩"],"answer":0,"explain":"使用验电笔时手不能接触笔尖金属探头（会直接触电），手应接触尾部金属挂钩或螺丝以构成回路。"},{"no":173,"stem":"钳形电流表在测量时，将导线在铁心上加绕一圈，其读数（ ）。","options":["不变","变大","变小","为零"],"answer":1,"explain":"钳形电流表利用电流互感器原理，导线在铁心上绕一圈相当于二次匝数增加一倍（穿心匝数为2），读数变为原来的2倍。"},{"no":174,"stem":"钳形电流表不能带电（ ）。","options":["读数","换量程","操作","动扳手"],"answer":1,"explain":"钳形电流表测量时不能带电转换量程，因为换挡瞬间电流互感器二次侧可能开路产生高压。应先退出导线再换挡。"},{"no":175,"stem":"交流接触器的电磁机构主要由（ ）、铁心和衔铁所组成。","options":["指示灯","手柄","电阻","线圈"],"answer":3,"explain":"交流接触器电磁机构由线圈、静铁芯和衔铁（动铁芯）组成。线圈通电产生磁场吸合衔铁，带动触点动作。"},{"no":176,"stem":"（ ）与其他电器安装在一起时，应将它安装在其他电器的下方。","options":["热继电器","时间继电器","速度继电器","中间继电器"],"answer":0,"explain":"热继电器应安装在其他电器下方，因为热继电器靠双金属片受热动作，装在下方不受上方电器热量影响，避免误动作。"},{"no":177,"stem":"变压器的基本工作原理是？（ ）","options":["电磁感应","电流的磁效应","欧姆定律","楞次定律"],"answer":0,"explain":"变压器基本工作原理是电磁感应（一次侧交变电流产生交变磁通，二次侧感应电动势）。"},{"no":178,"stem":"高压设备发生接地故障时，人员与接地点的安全距离应不小于多少米？（ ）","options":["8米","6米","5米","10米"],"answer":0,"explain":"高压设备发生接地故障时，室内不得接近故障点4m以内，室外不得接近8m以内，进入该范围须穿绝缘靴、戴绝缘手套。"},{"no":179,"stem":"变压器铁心采用硅钢片叠压的主要目的是？（ ）","options":["减小铁损","增大磁阻","提高效率","降低成本"],"answer":0,"explain":"铁芯采用硅钢片叠压主要目的是减小铁损（涡流损耗）。硅钢片电阻率高且彼此绝缘，可把涡流限制在薄片内大幅降低损耗。"},{"no":180,"stem":"携带式电气设备的接地线截面积应不小于？（ ）","options":["1.5mm²","2.5mm²","4mm²","6mm²"],"answer":0,"explain":"携带式电气设备的接地线（保护零线）截面积应不小于1.5mm²（铜芯软线），以保证故障时可靠导通。"},{"no":181,"stem":"隔离开关的主要作用是？（ ）","options":["隔离电路，形成明显断开点","切断负荷电流","切断短路电流","保护设备"],"answer":0,"explain":"隔离开关的主要作用是隔离电路、形成明显断开点，保证检修安全。它没有灭弧装置，不能切断负荷电流和短路电流。"},{"no":182,"stem":"电力系统的频率在我国规定为多少赫兹（Hz）？（ ）","options":["50Hz","60Hz","55Hz","45Hz"],"answer":0,"explain":"我国电力系统额定频率为50Hz（允许偏差±0.2Hz，小系统±0.5Hz）。"},{"no":183,"stem":"测量接地电阻应使用哪种仪表？（ ）","options":["接地电阻测量仪","兆欧表","万用表","钳形电流表"],"answer":0,"explain":"测量接地电阻应使用接地电阻测量仪（接地电阻测试仪/摇表），不能用兆欧表（测绝缘电阻）。"},{"no":184,"stem":"电压互感器的二次侧额定电压通常为多少伏？ （ ）","options":["100V","220V","380V","50V"],"answer":0,"explain":"电压互感器二次侧额定电压统一规定为100V（线电压100V，相电压100/√3 V），便于仪表标准化。"},{"no":185,"stem":"电力电缆敷设时，电缆弯曲半径应不小于电缆外径的（ ）倍？","options":["10倍","5倍","3倍","15倍"],"answer":0,"explain":"电缆敷设时弯曲半径一般不小于电缆外径的10倍（多芯电缆），过度弯曲会损伤绝缘和护套。"},{"no":186,"stem":"当变电站发生全站失压故障时，首先应采取的措施是？ （ ）","options":["检查主供电源情况，判断故障范围","立即手动合闸恢复供电","通知调度后等待指令","检查站内所有设备"],"answer":0,"explain":"全站失压应首先检查主供电源情况、判断故障范围，再采取恢复措施，不得盲目合闸，避免扩大事故。"},{"no":187,"stem":"变压器出现瓦斯保护动作跳闸时，以下哪项操作是错误的？（ ）","options":["立即检查瓦斯继电器内气体情况","取气样进行色谱分析","立即重新合闸试送","检查变压器油位、油色变化"],"answer":2,"explain":"瓦斯保护动作跳闸说明变压器内部有故障，严禁立即重新合闸试送（可能引发爆炸），必须检查气体、取气样分析、查明原因后方可送电。"},{"no":188,"stem":"高压断路器出现拒分故障时，应首先检查的是？ （ ）","options":["操作机构电源和控制回路","断路器灭弧室","断路器触头","继电保护装置"],"answer":0,"explain":"断路器拒分首先应检查操作机构电源和控制回路（最常见的拒动原因），如控制电源消失、控制回路断线、辅助接点接触不良等。"},{"no":189,"stem":"当发现母线电压异常升高超过额定电压110%时，应优先采取的措施是？ （ ）","options":["投入母线无功补偿电容器组","切除母线无功补偿电容器组","降低主变压器分接头","增加母线负荷"],"answer":1,"explain":"母线电压超过额定值110%属过电压，应切除无功补偿电容器组以减少无功注入、降低电压，同时防止电容器过压损坏。"},{"no":190,"stem":"线路发生单相接地故障时，对于小电流接地系统，允许继续运行的时间一般不超过？（ ）","options":["2小时","1小时","30分钟","15分钟"],"answer":0,"explain":"小电流接地系统单相接地后，因线电压仍对称、可继续供电，但非故障相电压升高，规程允许继续运行一般不超过2小时，期间应尽快查找处理。"},{"no":191,"stem":"当发现电容器组出现渗漏油现象时，应采取的措施是？（ ）","options":["立即将该电容器退出运行","加强监视，继续运行","更换密封垫后继续运行","减少电容器组负荷"],"answer":0,"explain":"电容器渗漏油说明外壳密封损坏，绝缘油流失会导致绝缘下降甚至爆炸，应立即将该电容器退出运行。"},{"no":192,"stem":"继电保护装置出现误动作跳闸后，应首先进行的工作是？（ ）","options":["检查保护装置动作记录和故障录波","立即重新合闸恢复供电","检查被保护设备有无故障","更换保护装置"],"answer":0,"explain":"保护误动作跳闸后，首先检查保护装置动作记录和故障录波，分析动作原因，不得盲目强送。"},{"no":193,"stem":"当变压器油温急剧升高超过规定值时，应首先采取的措施是？ （ ）","options":["检查冷却系统运行情况","立即将变压器停运","降低变压器负荷","打开放油阀降温"],"answer":0,"explain":"变压器油温急剧升高首先应检查冷却系统（风扇、油泵、散热器、冷却电源）是否正常，冷却失效是油温骤升最常见的原因。"},{"no":194,"stem":"隔离开关操作时发生瓷瓶断裂事故，应采取的措施是？（ ）","options":["立即停止操作，采取安全措施防止事故扩大","继续操作完成操作任务","立即汇报调度等待指令","组织人员更换瓷瓶"],"answer":0,"explain":"操作中发生瓷瓶断裂，应立即停止操作，采取安全措施（隔离、装设遮栏）防止事故扩大和人员伤害。"},{"no":195,"stem":"当发现GIS设备SF6气体压力降低报警时，应首先？ （ ）","options":["检查SF6气体泄漏情况","立即补气至额定压力","将该设备退出运行","关闭SF6气体阀门"],"answer":0,"explain":"GIS设备SF6压力降低报警，应首先检查泄漏点（用检漏仪检漏）并加强监视，视情况补气或停电处理，不得盲目补气掩盖缺陷。"},{"no":196,"stem":"变电站直流系统接地故障查找时，禁止采用的方法是？（ ）","options":["拉路法分段查找","使用直流接地检测仪","将直流系统正负极同时接地","逐级断开直流负荷回路"],"answer":2,"explain":"查找直流接地严禁将正负极同时接地（会造成直流短路，可能使保护误动或拒动），应采用拉路法或专用接地检测仪查找。"},{"no":197,"stem":"当发现电压互感器二次侧熔断器熔断时，应首先？（ ）","options":["检查二次侧回路有无短路","立即更换熔断器","将电压互感器停运","汇报调度"],"answer":0,"explain":"电压互感器二次熔断器熔断，应首先检查二次回路有无短路故障，排除后方可更换熔断器，否则换上还会熔断。"},{"no":198,"stem":"线路开关跳闸后，若重合闸未动作，运行人员应？（ ）","options":["检查线路有无明显故障迹象后汇报调度","立即手动重合闸","将开关转检修状态","检查重合闸装置"],"answer":0,"explain":"开关跳闸重合闸未动作，应检查线路有无明显故障迹象（如烟火、断线、异物）并汇报调度，由调度决定是否试送，运行人员不得自行强送。"},{"no":199,"stem":"变压器差动保护动作跳闸，且伴随瓦斯保护动作，说明故障位于？（ ）","options":["变压器内部","差动保护范围内的外部线路","电流互感器回路","保护装置本身"],"answer":0,"explain":"差动保护与瓦斯保护同时动作，两者都反映变压器内部故障，说明故障位于变压器内部。差动保护反映电气故障，瓦斯保护反映内部油分解产气。"},{"no":200,"stem":"当变电站发生火灾时，首先应采取的措施是？ （ ）","options":["切断火灾设备的电源","使用灭火器灭火","拨打火警电话","组织人员撤离"],"answer":0,"explain":"变电站发生火灾应首先切断火灾设备电源，防止触电和电弧扩大事故，然后再灭火并报警。"}],"blank":[{"no":1,"stem":"巡视人员应熟练掌握设备巡视的四种标准方法为：____、耳听法、鼻嗅法、____。","answer":["目测法","手触法"],"explain":"设备巡视四种标准方法：目测法（看外观、油位、指示）、耳听法（听声音有无异常）、鼻嗅法（闻有无焦糊异味）、手触法（触外壳检查温度、振动，注意不能触带电部位）。"},{"no":2,"stem":"操作票的填写必须按两票细则的规定执行并做到四把关即：受令复诵关、____关、模拟核对关、____关。","answer":["填票审核","操作监护"],"explain":"操作票'四把关'：受令复诵关、填票审核关、模拟核对关、操作监护关。"},{"no":3,"stem":"操作前必须进行四对照，即对照设备的名称、____、实际位置、____。","answer":["编号","拉合方向"],"explain":"操作前'四对照'：对照设备名称、编号、实际位置、拉合方向，确认无误方可操作，是防止走错间隔的关键措施。"},{"no":4,"stem":"“五清”就是：____、____、____、问清、点清。","answer":["看清","讲清","听清"],"explain":"'五清'：看清（看清设备名称编号）、讲清（操作中讲清指令）、听清（听清复诵）、问清（有疑问问清楚）、点清（操作项目点清），确保操作准确无误。"},{"no":5,"stem":"在全部停电和部分停电的电气设备上工作时，必须完成的枝术措施有____、____、____、____、____ 。","answer":["停电","验电","挂接地线","装设遮栏","悬挂标志牌"],"explain":"电气设备上工作的安全技术措施：停电、验电、装设接地线、悬挂标示牌和装设遮栏（围栏）。这四项是保证检修人员安全的基本措施，缺一不可。"},{"no":6,"stem":"拉保险时先拉____，后拉____，合保险时与此相反。","answer":["正极","负极"],"explain":"直流回路拉合保险顺序：拉保险先拉正极后拉负极；合保险顺序相反，先合负极后合正极。这样可防止因产生电弧或寄生回路造成保护误动。"},{"no":7,"stem":"装卸高压可熔性保险或切换CT二次回路时准备____、____。","answer":["护目镜","绝缘垫"],"explain":"装卸高压可熔保险或切换CT二次回路时，应戴护目镜（防电弧伤眼）并站在绝缘垫上（防触电）。"},{"no":8,"stem":"操作保护压板等二次设备时，应先核对____和____。","answer":["保护屏名称","压板状态"],"explain":"操作保护压板等二次设备前，必须先核对保护屏名称（确认屏柜正确）和压板状态（确认当前投退状态），防止误投误退压板。"},{"no":9,"stem":"操作时，不能更换操作人，更换时应重新____。","answer":["模拟"],"explain":"操作过程中不得更换操作人，确需更换时必须重新进行模拟预演，确保新操作人完全掌握操作内容和步骤。"},{"no":10,"stem":"蓄电池室温度应经常保持在____之间，保持良好的通风和照明。","answer":["10~C-35~C"],"explain":"蓄电池室温度应保持在10℃-35℃（本题原文档标注为10~C-35~C，即10℃至35℃），温度过低容量下降，过高加速极板老化，须保持通风照明良好。"},{"no":11,"stem":"设备巡视原则是全部一、二次设备均应巡视到位，达到____、____。发现运行中的开关严重____时，应采取____的措施。","answer":["不漏项","不留死角","漏油","禁止跳闸"],"explain":"设备巡视原则：一、二次设备均巡视到位，不漏项、不留死角。发现运行中开关严重漏油时，应采取禁止跳闸措施（取下操作保险或加装机械闭锁），防止跳闸时因灭弧能力不足引发爆炸。"},{"no":12,"stem":"安全电压为 ____V 以下；安全电流为____mA 以下。","answer":["36","10"],"explain":"安全电压36V以下，安全电流10mA以下。人体通过工频电流超过50mA·s即有致命危险，故安全电流定为10mA。"},{"no":13,"stem":"带电设备着火时应使用 ____ 、____、____灭火器，不得使用 ____灭火器灭火。","answer":["干粉","1211","二氧化碳","泡沫"],"explain":"带电设备着火应使用干粉、1211、二氧化碳等不导电灭火剂；严禁使用泡沫灭火器（泡沫含水导电，会造成触电和短路）。"},{"no":14,"stem":"变电站（所）常用直流电源有 ____ 、 硅整流 、 电容储能 。","answer":["蓄电池"],"explain":"变电站直流电源三种形式：蓄电池（最可靠，作后备电源）、硅整流（将交流变为直流）、电容储能（用于跳闸电源补偿）。"},{"no":15,"stem":"变电站（所）事故照明必须是____电源 ，与常用 照明回路不能混接 。","answer":["独立"],"explain":"事故照明必须是独立电源，不得与常用照明回路混接，以保证常用照明失电时事故照明仍能可靠投入。"},{"no":16,"stem":"验电装拆接地线的操作术语是 ____ 、____ 。","answer":["装设","拆除"],"explain":"接地线的操作术语规范为'装设接地线'和'拆除接地线'，操作票中必须使用规范术语。"},{"no":17,"stem":"已执行的操作票注明“ ____”字样，作废的操作应注明“____”字样。","answer":["已执行","作废"],"explain":"已执行的操作票加盖'已执行'章，作废的操作票加盖'作废'章，并保存备查，不得撕毁。"},{"no":18,"stem":"在电阻串联电路中，流过各电阻的____都相等，而各电阻的____及____的分配则与电阻值成正比。","answer":["电流强度","电压","功率"],"explain":"串联电路电流处处相等（I相同）；由 U=IR 和 P=I²R，各电阻的电压及功率分配与电阻值成正比。"},{"no":19,"stem":"从电源一端经负载回到电源另一端的电路称为____。","answer":["外电路"],"explain":"外电路是指电源一端经负载回到电源另一端的电路；电源内部的电路称为内电路。"},{"no":20,"stem":"表示交流电变化快慢的三个物理量分别是____、____和____。","answer":["频率","周期","角频率"],"explain":"表示交流电变化快慢的三个物理量：频率 f、周期 T、角频率 ω（ω=2πf）。三者知其一即知其余。"},{"no":21,"stem":"电路通常有____、____和____三种状态。","answer":["通路","断路","短路"],"explain":"电路三种状态：通路（正常工作）、断路（开路，电路断开无电流）、短路（电源或负载两端被短接，电流极大）。"},{"no":22,"stem":"继电器是一种根据____或____的变化，____或____控制电路，实现自动控制和保护电力拖动装置的电器。","answer":["电量","非电量","接通","断开"],"explain":"继电器是根据电量（电压、电流等）或非电量（温度、压力、速度等）的变化，接通或断开控制电路的自动控制电器。"},{"no":23,"stem":"变压器最主要的额定值有额定 ____、额定 ____ 和额定____。","answer":["容量","电压","电流"],"explain":"变压器三大额定值：额定容量（kVA）、额定电压（V/kV）、额定电流（A）。"},{"no":24,"stem":"测量电流时，要根据电流大小选择适当量程的____ ，不能使电流大于电流表的____。","answer":["电流表","最大量程"],"explain":"测电流时选用适当量程的电流表，被测电流不得超过电流表最大量程，否则烧毁仪表。"},{"no":25,"stem":"兆欧表俗称____，是用于测量各种电气设备____的仪表。","answer":["摇表","绝缘电阻"],"explain":"兆欧表俗称摇表（也有电子式），用于测量电气设备绝缘电阻，输出电压有500V、1000V、2500V等等级。"},{"no":26,"stem":"____是最严重的触电事故。","answer":["电击"],"explain":"电击（电流通过人体内部）是最严重的触电事故，可造成心室颤动、呼吸停止致死；电伤（电弧烧伤等）属外部伤害。"},{"no":27,"stem":"单相整流变压器的容量可按____来计算。","answer":["P=UI"],"explain":"单相整流变压器容量按 P=UI 计算，即二次侧电压与电流的乘积。"},{"no":28,"stem":"用电设备最理想的工作电压就是它的____ 。","answer":["额定电压"],"explain":"用电设备在最理想的工作电压即额定电压下运行时，效率最高、寿命最长，电压偏差过大会影响性能和寿命。"},{"no":29,"stem":"验电器分____验电笔和____验电器两种。","answer":["低压","高压"],"explain":"验电器分低压验电笔（验电笔，适用60-500V）和高压验电器（用于高压设备验电）两种。"},{"no":30,"stem":"用摇表测量绝缘电阻时，要求转速达到____。","answer":["120r/min"],"explain":"用摇表（手摇式）测量绝缘电阻时，转速应达到120r/min，转速过低输出电压不足会导致读数偏低。"},{"no":31,"stem":"为提高功率因数，传统的日光灯需加装相应规格的____。","answer":["电容器"],"explain":"传统电感式日光灯功率因数低（约0.5），需并联相应规格的电容器进行无功补偿以提高功率因数。"},{"no":32,"stem":"将直流接触器接在它额定电压相等的交流电源上，接触器将____。","answer":["启动不起来"],"explain":"直流接触器接在等电压交流电源上启动不起来，因为交流电过零时电磁吸力为零，衔铁会频繁振动无法可靠吸合（且直流线圈感抗小、交流下电流过大）。"},{"no":33,"stem":"____有规则的移动就形成电流，电流的方向规定为____运动的方向。","answer":["电荷","正电荷"],"explain":"电荷有规则的定向移动形成电流；规定正电荷定向移动的方向为电流方向（与电子运动方向相反）。"},{"no":34,"stem":"在电阻串联电路中，流过各电阻的____都相等，而各电阻的____及____的分配则与电阻值成正比。","answer":["电流","电压","功率"],"explain":"串联电路电流处处相等（I相同）；由 U=IR 和 P=I²R，各电阻的电压及功率分配与电阻值成正比。"},{"no":35,"stem":"在内电路中，电流的方向与电动势方向____；在外电路中，电流的方向与电压的方向____。","answer":["相同","相同"],"explain":"内电路中电流方向与电动势方向相同（由低电位到高电位）；外电路中电流方向与电压方向相同（由高电位到低电位）。"},{"no":36,"stem":"把交流电变成直流电的过程叫____。","answer":["整流"],"explain":"把交流电变成直流电的过程叫整流，由二极管、晶闸管等整流元件完成。"},{"no":37,"stem":"白炽灯是靠通电后灯丝____至____而发光的。","answer":["发热","白炽化"],"explain":"白炽灯靠电流通过灯丝发热至白炽化（高温炽热）而发光，属热辐射光源。"},{"no":38,"stem":"白炽灯中，螺口灯座的螺纹圈应接于电源的____上。","answer":["零线"],"explain":"螺口灯座的螺纹圈（外壳）应接于电源零线上，中心触点接火线，这样更换灯泡时人手不易触及带电部分，保证安全。"},{"no":39,"stem":"变压器的基本构造是由____和____两大部分组成的。","answer":["铁芯","绕阻"],"explain":"变压器基本构造由铁芯（磁路）和绕组（电路）两大部分组成。"},{"no":40,"stem":"表示交流电大小的三个物理量分别是____、____和____。","answer":["最大值","平均值","有效值"],"explain":"表示交流电大小的三个物理量：最大值（幅值）、平均值、有效值（有效值最常用，仪表读数多为有效值）。"},{"no":41,"stem":"并联电容器的总容量等于各个电容器容量____。","answer":["之和"],"explain":"并联电容器总容量等于各电容器容量之和（C=C1+C2+…），与电阻并联的计算规律相反。"},{"no":42,"stem":"磁极间相互作用的规律是同极性磁极互相____，异极性磁极互相____。","answer":["排斥","吸引"],"explain":"磁极间相互作用：同极性（同名磁极）互相排斥，异极性（异名磁极）互相吸引。与电荷'同性相斥、异性相吸'规律一致。"},{"no":43,"stem":"促使绝缘材料老化的主要原因，在低压设备中是____，在高压设备中是____。","answer":["过热","局部放电"],"explain":"绝缘老化主因：低压设备中主要是过热（长期高温使绝缘变脆）；高压设备中主要是局部放电（电晕、气隙放电侵蚀绝缘）。"},{"no":44,"stem":"大小、方向都不随时间变化的电流叫____。","answer":["直流"],"explain":"大小和方向都不随时间变化的电流叫直流电（恒定直流）；方向不变大小变化的是脉动直流。"},{"no":45,"stem":"单位时间内通过导体任一横截面的电量叫____，用符号____表示，单位为____。","answer":["电流强度","I","A"],"explain":"单位时间内通过导体任一横截面的电量叫电流强度，简称电流，符号 I，单位安培（A）。I=Q/t。"},{"no":46,"stem":"低压验电笔适用的电压范围是____。使用时，手要触及笔尾的____。","answer":["60～500V","金属体"],"explain":"低压验电笔适用电压范围60-500V；使用时手必须触及笔尾金属体（构成回路氖泡才发光），但绝不能触及笔尖金属探头。"},{"no":47,"stem":"电路中产生电流的条件是：电路必须____，电路中必须有____。","answer":["闭合","电源"],"explain":"产生电流的两个必要条件：电路必须闭合（形成通路），电路中必须有电源（提供电动势）。"},{"no":48,"stem":"电线电缆一般由____、____、____三部分组成。","answer":["线芯","绝缘层","保护层"],"explain":"电线电缆由线芯（导体，传输电能）、绝缘层（隔离带电体）、保护层（防护外护套）三部分组成。"},{"no":49,"stem":"电压互感器使用时，一次绕组应____在被测电路上，二次绕组绝对不允许____。","answer":["并联","短路"],"explain":"电压互感器一次绕组应并联在被测电路上（测电压须并联）；二次绕组绝对不允许短路（短路会产生大电流烧毁互感器），二次侧必须可靠接地。"},{"no":50,"stem":"各项电气工作应严格执行“____、____、____、____”的规定。","answer":["装得安全","拆得彻底","检查经常","修理及时"],"explain":"电气工作'四项要求'：装得安全、拆得彻底、检查经常、修理及时。这是电气安装检修工作的基本规范。"},{"no":51,"stem":"导线剖削时，无论采用何种工具和剥削方法，一定不能损伤导线内部____。","answer":["线芯"],"explain":"导线剖削（剥线）时不得损伤内部线芯，线芯受损会减小截面积、降低载流量并易折断，造成接触不良发热。"},{"no":52,"stem":"一个完整的照明电路由电度表、总开关、____、照明单元和____等组成。","answer":["分控开关","导线"],"explain":"完整照明电路由电度表（计量）、总开关、分控开关（分支控制）、照明单元（灯具）和导线等组成。"},{"no":53,"stem":"二极管的最大特点是____。","answer":["单向导通"],"explain":"二极管的最大特点是单向导电性（单向导通）：正向导通、反向截止，这是整流、检波等电路的基础。"},{"no":54,"stem":"三相异步电动机中，电动机旋转的转向取决于三相电流的____。","answer":["相序"],"explain":"三相异步电动机的转向取决于三相电流的相序；任意调换两相接线即可改变转向（反转）。"},{"no":55,"stem":"测量电流时，要根据电流大小选择适当量程的电流表，不能使电流大于电流表的____。","answer":["最大量程"],"explain":"测电流时选用适当量程的电流表，被测电流不得超过电流表最大量程，否则烧毁仪表。"},{"no":56,"stem":"变频器由____和控制电路组成。","answer":["主电路"],"explain":"变频器由主电路（整流、滤波、逆变）和控制电路组成，主电路完成电能变换，控制电路实现调节与保护。"},{"no":57,"stem":"在电气线路的维护检修中，一定要遵循电力开关设备的____。","answer":["安全操作程序"],"explain":"电气线路维护检修必须遵循电力开关设备的安全操作程序，按规程办事，杜绝违章。"},{"no":58,"stem":"接触器的电磁机构由____、____和____三部分组成。","answer":["线圈","动铁心","静铁心"],"explain":"接触器电磁机构由线圈、动铁心（衔铁）和静铁心三部分组成。线圈通电产生电磁吸力使衔铁动作。"},{"no":59,"stem":"流过导体的电流与加在导体两端的____成正比，与导体的____成反比。","answer":["电压","电阻"],"explain":"欧姆定律：流过导体的电流与导体两端电压成正比，与导体电阻成反比，即 I=U/R。"},{"no":60,"stem":"日光灯点燃后镇流器的作用是____和____。","answer":["降压","限流"],"explain":"日光灯点燃后，镇流器起降压和限流作用，限制灯管工作电流并维持灯管电压（启动时还产生高压点亮灯管）。"},{"no":61,"stem":"日光灯主要由镇流器、____和____组成。","answer":["启辉器","灯管"],"explain":"日光灯由镇流器、启辉器（跳泡）和灯管三部分组成（电子镇流器日光灯无启辉器）。"},{"no":62,"stem":"不论是何原因造成开关一相相通，现场值班员确认无误后立即手动____，再报告调度。","answer":["断开"],"explain":"开关一相相通（单相断不开）属严重故障，值班员确认后应立即手动断开该开关，再报告调度处理。"},{"no":63,"stem":"工作票、操作票、交接班制、巡回检查制、____-----两票、三制。","answer":["设备定期试验轮换制"],"explain":"'两票三制'：两票指工作票、操作票；三制指交接班制、巡回检查制、设备定期试验轮换制。"},{"no":64,"stem":"使用万用表进行测量工作时，使用前应按测试的项目要求选取好挡位及使用量程的倍率，以防____及误测。","answer":["烧表"],"explain":"使用万用表前必须按测试项目选好挡位和量程倍率，防止烧表（用电阻挡测电压、用小量程测大电压都会烧毁仪表）。"},{"no":65,"stem":"按压与人工呼吸比例：按压与人工呼吸比例关系通常是，单人为____，双人复苏为5：1，婴儿、儿童为5：1。","answer":["15：2"],"explain":"心肺复苏按压与人工呼吸比例：单人15:2，双人5:1，婴儿和儿童5:1。"},{"no":66,"stem":"填写的工作票出现错字和漏字最多不允许超过3个字处需要修改时，必须保持清晰。在错字上以“=“横线划掉，填加字以”√“符号填写，并由修改人在修改处____。","answer":["盖章"],"explain":"工作票错字漏字修改：错字用'='横线划掉，添加字用'√'符号填写，并由修改人在修改处盖章（签名）确认。"},{"no":67,"stem":"工作许可人应按工作票要求在检修设备周围设一留有通道口的封闭式遮栏，并在周围背向带电设备的遮栏上挂适量的____标示牌，在通道入口处挂“从此进出”标志牌。","answer":["“止步高压危险”"],"explain":"检修设备周围设封闭式遮栏，背向带电设备的遮栏上挂'止步，高压危险！'标示牌，通道入口处挂'从此进出！'标示牌。"},{"no":68,"stem":"电气设备操作后的位置检查应以设备实际位置为准，无法看到实际位置时，可通过设备机械位置指示、电气指示、仪表及各种遥测、遥信信号的变化，且至少应有____及以上指示已同时发生对应变化，才能确认该设备已操作到位。","answer":["两个"],"explain":"设备操作后的位置检查，无法看到实际位置时，至少应有两个及以上指示（机械位置、电气指示、仪表、遥测遥信等）同时发生对应变化，才能确认操作到位。"},{"no":69,"stem":"操作人在操作过程中始终处于监护人的视线中。操作开关前后要有看电流、电力、电压表和____的意识，双方都要核对所要操作项目。","answer":["灯光指示"],"explain":"操作开关前后要观察电流、电力（功率）、电压表和灯光指示的变化，监护人操作人双方共同核对操作项目。"},{"no":70,"stem":"紧急情况下的事故处理或____不能操作时，需要使用万能钥匙，必须经运行主任或所长批准。取万能钥匙，应撕下“封存袋”上口封条，并将使用情况记入运行记录簿及解锁总钥匙使用记录簿内。","answer":["程序锁具损坏"],"explain":"万能钥匙（解锁钥匙）仅在紧急事故处理或程序锁具损坏时使用，须经运行主任或所长批准，并撕下封条、记入运行记录簿。"},{"no":71,"stem":"在带电的二次设备上进行清扫应____进行，并防止误触误碰。","answer":["两人"],"explain":"在带电的二次设备上清扫应两人进行（一人操作一人监护），防止误触误碰造成保护误动或人身触电。"},{"no":72,"stem":"测____的导线处应设一测试点，在其引下线固定位置处进行测量，每次测量均测该测试点。","answer":["铁芯接地电流"],"explain":"测铁芯接地电流应设固定测试点，在引下线固定位置测量，每次均测该点，便于前后数据比较判断是否正常。"},{"no":73,"stem":"巡视分日常巡视、定期巡视、____。","answer":["特殊巡视"],"explain":"设备巡视分日常巡视、定期巡视、特殊巡视（恶劣天气、异常运行、新投运等情况下增加）。"},{"no":74,"stem":"运行人员按照设备验收标准对检修及涉及设备进行竣工验收；验收合格后，设备恢复到____。","answer":["初始状态"],"explain":"设备检修竣工验收合格后，恢复到初始状态（常设遮栏、标示牌恢复，安全措施拆除），方可投入运行。"},{"no":75,"stem":"有载调压变压器并列运行时，其有载调压操作应____或同步进行。","answer":["轮流逐级"],"explain":"有载调压变压器并列运行时，调压操作应轮流逐级进行或同步进行，避免两台变压器分接位置不一致产生环流。"},{"no":76,"stem":"发生事故时，事故单位应主动采取措施，消除对____和设备安全的威胁，限制事故的发展。","answer":["人身"],"explain":"发生事故时优先消除对人身和设备安全的威胁，再限制事故发展，先救人后救设备。"},{"no":77,"stem":"变压器发生内部故障时的主保护是____保护。","answer":["瓦斯"],"explain":"变压器内部故障的主保护是瓦斯保护（重瓦斯跳闸、轻瓦斯发信），能灵敏反映内部匝间短路、铁芯故障等。"},{"no":78,"stem":"一般变压器的上层油温不能超过____","answer":["85度"],"explain":"一般变压器上层油温不能超过85℃（强油风冷变压器顶层油温不超过85℃），过高会加速绝缘老化。"},{"no":79,"stem":"电流互感器的不完全星形接线，在运行中____反映所有的接地故障。","answer":["不能"],"explain":"电流互感器不完全星形接线（两相式，V形接线）中缺少一相，运行中不能反映所有接地故障（未装CT的那一相单相接地无法反映）。"},{"no":80,"stem":"铁芯多点接地，接地电流较大时，应安排检修处理。在缺陷消除前，可采取措施将电流限制在____mA以下，如串入电阻等，并加强监视。","answer":["100"],"explain":"铁芯多点接地时接地电流较大应安排检修，缺陷消除前可串入电阻将电流限制在100mA以下并加强监视。"},{"no":81,"stem":"变压器中性点接地属于____。","answer":["工作接地"],"explain":"变压器中性点接地属于工作接地，为系统提供电位参考点、降低绝缘水平、便于继电保护。"},{"no":82,"stem":"新投运的分接开关，在投运1—2年后或切换 ____后，应将切换开关吊出检查，此后可按实际情况确定检查周期。","answer":["5000次"],"explain":"新投运分接开关在投运1-2年后或切换5000次后，应将切换开关吊出检查，之后按实际情况确定检查周期。"},{"no":83,"stem":"继电保护装置定值以____为准。","answer":["一次值"],"explain":"继电保护装置定值以一次值为准（一次系统实际值），二次值需按CT、PT变比折算后整定。"},{"no":84,"stem":"蓄电池组正常运行中以____方式运行。","answer":["浮充电"],"explain":"蓄电池组正常运行时以浮充电方式运行，即与充电机并列，正常由充电机带负荷并向蓄电池浮充，补充自放电损失。"},{"no":85,"stem":"当母差来____信号时，应立即停用母差。","answer":["“交流电流回路断线”"],"explain":"母差保护发出'交流电流回路断线'信号时，应立即停用母差（防止因电流回路异常造成误动或拒动）。"},{"no":86,"stem":"____信号表示时，母差保护仍可继续运行，但回路上不允许作业。","answer":["电压断线"],"explain":"'电压断线'信号时母差保护仍可继续运行（只是失去电压闭锁），但回路上不允许作业，防止作业时误动。"},{"no":87,"stem":"运行中的高频保护不允许单独一侧断开高频保护____。","answer":["直流电源"],"explain":"运行中的高频保护不允许单独一侧断开高频保护直流电源，否则会造成保护通道中断、区内故障时拒动。"},{"no":88,"stem":"操作中操作人在前，监护人在后，两人的步调、相互位置要协调，并保证操作人在操作过程中始终处于监护人的____中。","answer":["视线"],"explain":"操作中操作人在前、监护人在后，操作人应始终处于监护人视线中，便于监护和及时制止误操作。"},{"no":89,"stem":"每到一操作设备前，监护人及操作人必须先核对设备位置、名称、____和运行状态与操作内容是否相符，确认符合后方可执行操作。","answer":["编号"],"explain":"每到一操作设备前，监护人及操作人必须先核对设备位置、名称、编号和运行状态与操作内容相符（即'四对照'），确认后方可执行。"},{"no":90,"stem":"交接班过程中发生事故应____交接班，由交班人员负责处理，接班人员协助。","answer":["停止"],"explain":"交接班过程中发生事故应立即停止交接班，由交班人员负责处理、接班人员协助，避免因交接不清延误事故处理。"},{"no":91,"stem":"使用摇表应在其额定转速每分钟____转时,观察指针读数。","answer":["120"],"explain":"使用摇表应在其额定转速每分钟120转时观察指针读数，转速不足会使输出电压偏低、读数不准。"},{"no":92,"stem":"运行中的开关出现分、合闸闭锁、压力异常等紧急情况，值班人员应立即将其改为____状态，并作好防慢分措施，再汇报调度。","answer":["非自动"],"explain":"运行中开关出现分合闸闭锁、压力异常等紧急情况，值班人员应立即将其改为非自动状态（断开控制电源，防止误动或慢分闸），做好防慢分措施，再汇报调度。"},{"no":93,"stem":"变压器的并列运行条件相位相同接线组别相同；____；短路阻抗相等或相近。","answer":["电压比相等"],"explain":"变压器并列运行条件：①接线组别相同（相位相同）；②电压比相等；③短路阻抗相等或相近。此外容量比不宜超过3:1。"},{"no":94,"stem":"电动操作的刀闸，当操作失灵时，应查明原因。改手动操作时，应当断开____的电源。","answer":["电动回路"],"explain":"电动操作刀闸失灵改手动操作时，应先断开电动回路电源，防止手动操作时电机突然启动伤人。"},{"no":95,"stem":"高压设备发生接地时，室内不得接近故障点____米以内，室外不得接近故障点____米以内。进入上述范围人员必须穿绝缘靴，接触设备的外壳和构架时，应戴绝缘手套。","answer":["4","8"],"explain":"高压设备发生接地时，室内不得接近故障点4米以内，室外不得接近8米以内；进入该范围须穿绝缘靴，接触设备外壳构架时须戴绝缘手套。"},{"no":96,"stem":"操作前必须进行四对照，即对照设备的____、____、实际位置、____。","answer":["名称","编号","拉合方向"],"explain":"操作前'四对照'：对照设备名称、编号、实际位置、拉合方向，确认无误方可操作，是防止走错间隔的关键措施。"}],"judge":[{"no":1,"stem":"电流的方向规定为电子的运动方向。","answer":false,"explain":"错。规定正电荷定向移动的方向为电流方向，与电子（负电荷）运动方向相反。"},{"no":2,"stem":"大小随时间改变的电流称为直流电流。","answer":false,"explain":"错。方向不随时间改变的电流才叫直流。大小变、方向不变的称脉动直流；方向和大小都随时间变的是交流。"},{"no":3,"stem":"在直流电路中电容相当于开路。","answer":true,"explain":"对。直流稳态下电容充电完成后无电流通过，相当于开路（隔直作用）。"},{"no":4,"stem":"沿电压的方向上电位是逐渐减小的。","answer":true,"explain":"对。电压方向即电位降低的方向，沿电压方向（电流方向）电位逐渐减小。"},{"no":5,"stem":"电荷之间存在作用力，同性电荷互相排斥，异性电荷互相吸引。","answer":true,"explain":"对。同性电荷相斥、异性电荷相吸，是电荷间相互作用的基本规律。"},{"no":6,"stem":"绝缘体不可能导电。","answer":false,"explain":"错。绝缘体并非绝对不导电，只是电阻率极高。在高压、高温或受潮时绝缘体也会被击穿而导电。"},{"no":7,"stem":"同频正弦量的相位差就是它们的初相之差。","answer":true,"explain":"对。同频率正弦量的相位差等于它们的初相之差，与时间无关，是恒定值。"},{"no":8,"stem":"对称三相电路在任一瞬间三个负载的功率之和都为零。","answer":false,"explain":"错。对称三相电路任一瞬间三相功率之和为常数（等于总有功功率3倍相功率），但不为零。"},{"no":9,"stem":"在零初始条件下，刚一接通电源瞬间，电感元件相当于短路。","answer":false,"explain":"错。零初始条件下刚接通电源瞬间，电感电流不能突变（i(0+)=0），电感相当于开路，而非短路。电容才在瞬间相当于短路。"},{"no":10,"stem":"RL串联的正弦交流电路中，{F}。","answer":false,"explain":"错。RL 串联电路中电流<b>处处相等</b>，即 I = I_L = I_R。公式 I总 = I_L + I_R 是并联电路的电流关系（并联支路电流代数和），用在串联电路上是错的。串联电路是电压相加：U = U_L + U_R（相量和）。","formula":{"F":"data:image/png;base64,"}},{"no":11,"stem":"电阻与导线长度L成正比，与导线横截面积成反比。","answer":true,"explain":"对。由 R=ρL/S，导体电阻与长度成正比、与横截面积成反比。"},{"no":12,"stem":"电阻率也称电阻系数，它指某种导体作成长1m，横截面积1{F}的导体，在温度20℃时的电阻值。","answer":true,"explain":"对。电阻率定义为：用某种导体材料制成长 1m、横截面积 1mm² 的导体，在温度 20℃ 时所具有的电阻值，单位 Ω·mm²/m。","formula":{"F":"data:image/png;base64,"}},{"no":13,"stem":"电阻率用“ρ”表示，是一常数，反映了导体导电性的好坏，电 阻率大，说明导电性能差，电阻率小，说明导电性好。","answer":true,"explain":"对。电阻率反映材料导电性能：电阻率越大导电性越差，越小导电性越好。银、铜、铝的电阻率依次增大。"},{"no":14,"stem":"导电材料的电阻，不仅和材料有关，尺寸有关，而且还会受到外 界环境的影响，金属导体的电阻值，随温度升高而增大，非金属导体 电阻值，却随温度的上升而减少。","answer":true,"explain":"对。金属导体电阻随温度升高而增大（正温度系数）；非金属（如碳、电解液）电阻随温度升高而减小（负温度系数）。"},{"no":15,"stem":"欧姆定律是用来说明电路中电压、电流、电阻，这三个基本物理 量之间关系的定律，它指出：在一段电路中流过电阻的电流I，与电 阻R两端电压成正比，而与这段电路的电阻成反比。","answer":true,"explain":"对。欧姆定律 I=U/R：流过电阻的电流与两端电压成正比，与电阻成反比。"},{"no":16,"stem":"全电路欧姆定律是用来说明，在单一闭合电路中，电压、电流、 电阻之间基本关系定律，即在单一闭合电路中，电流与电源的电动势 成正比，与电路电源的内阻和外阻之和成反比。","answer":true,"explain":"对。全电路欧姆定律 I=E/(R+r)：电流与电动势成正比，与内阻和外阻之和成反比。"},{"no":17,"stem":"单位时间内电场力所做的功叫做电功率，电功率反映了电场力移 动电荷作功的速度。","answer":true,"explain":"对。电功率 P=W/t，表示单位时间内电场力所做的功，反映做功快慢。"},{"no":18,"stem":"当电流流过导体时，由于导体具有一定的电阻，因此就要消耗一 定的电能，这些电能转变的热能，使导体温度升高，这种效应秒为电 流的热效应。","answer":true,"explain":"对。电流通过导体发热的现象叫电流的热效应（焦耳定律 Q=I²Rt）。"},{"no":19,"stem":"电气上的“地”的含义不是指大地，而是指电位为零的地方。","answer":true,"explain":"对。电气上的'地'指电位为零的参考点，不一定是大地。"},{"no":20,"stem":"接地的中性点又叫零点。","answer":false,"explain":"错。接地的中性点叫零点是从属概念混淆：中性点接地后称为'零点'的说法不准确，通常把直接接地的中性点称为零点，其引出线为零线。此题判错（常见题库判定）。"},{"no":21,"stem":"当磁力线、电流和作用力这三者的方向互相垂直时，可以用右手 定则来确定其中任一量的方向。","answer":false,"explain":"错。磁力线、电流、作用力三者方向互相垂直时用左手定则判断；右手定则用于判断导体切割磁力线产生的感应电动势方向。"},{"no":22,"stem":"叠加原理适用于各种电路。","answer":false,"explain":"错。叠加原理只适用于线性电路，对非线性电路（含二极管、铁芯线圈等）不适用。"},{"no":23,"stem":"由于外界原因，正电荷可以由一个物体转移到另一个物体。","answer":false,"explain":"错。金属导体中正电荷（原子核）不能自由移动，实际转移的是负电荷（电子）。"},{"no":24,"stem":"载流导体在磁场中要受到力的作用。","answer":true,"explain":"对。载流导体在磁场中受电磁力作用（左手定则），这是电动机的基本原理。"},{"no":25,"stem":"铁芯绕组上的交流电压与电流的关系是非线性的。","answer":true,"explain":"对。铁芯绕组因磁饱和，其电压与电流关系是非线性的（磁通与励磁电流不成正比）。"},{"no":26,"stem":"交流铁芯绕组的电压、电流、磁能能同为正弦波。","answer":false,"explain":"错。由于铁芯饱和，交流铁芯绕组的电压、电流、磁通不能同时为正弦波，磁通为正弦时励磁电流为尖顶波。"},{"no":27,"stem":"交流电压在每一瞬间的数值，叫交流电的有效值。","answer":false,"explain":"错。交流电每一瞬间的数值叫瞬时值；有效值是与直流电热效应等效的值。"},{"no":28,"stem":"正弦交流电变化一周，就相当于变化了2π弧度（360°）。","answer":true,"explain":"对。正弦交流电变化一周对应电角度2π弧度，即360°。"},{"no":29,"stem":"有功功率和无功功率之和称为视在功率。","answer":false,"explain":"错。视在功率 S=√(P²+Q²)，是有功功率与无功功率的相量和，不是代数和。"},{"no":30,"stem":"串联电路中，电路两端的总电压等于各电阻两端的分压之和。","answer":true,"explain":"对。串联电路总电压等于各元件分压之和（基尔霍夫电压定律）。"},{"no":31,"stem":"参考点改变，电路中两点间电压也随之改变。","answer":false,"explain":"错。电路中两点间的电压（电位差）与参考点选择无关，不随参考点改变而改变；改变的是各点的电位值。"},{"no":32,"stem":"电阻元件的电压和电流方向总是相同的。","answer":true,"explain":"对。电阻是耗能元件，其电压与电流方向总是相同（同相），符合欧姆定律的关联参考方向。"},{"no":33,"stem":"变压器最热处是变压器的下层1/3处。","answer":false,"explain":"错。变压器最热处是上层（上层油温最高），绕组最热点通常在绕组高度的上部约1/3处，不是下层。"},{"no":34,"stem":"变压器铜损等于铁损时最经济。","answer":true,"explain":"对。铜损（可变损耗）等于铁损（固定损耗）时变压器效率最高、运行最经济。"},{"no":35,"stem":"变压器空载时无电流流过。","answer":false,"explain":"错。变压器空载时一次绕组仍有空载（励磁）电流流过，约为额定电流的2%-10%。"},{"no":36,"stem":"变压器中性点接地属于工作接地。","answer":true,"explain":"对。变压器中性点接地属于工作接地，为系统提供电位参考、降低绝缘水平。"},{"no":37,"stem":"变压器外部有穿越电流流过时，气体继电器动作。","answer":true,"explain":"对。变压器外部有穿越电流（如区外故障短路电流）流过时，可能使气体继电器动作（需正确区分内部故障）。"},{"no":38,"stem":"在变压器中性点装设消弧线圈目的是补偿电网接地时电容电流。","answer":true,"explain":"对。消弧线圈装在中性点，单相接地时提供感性电流补偿接地电容电流，使电弧自行熄灭。"},{"no":39,"stem":"变压器温度升高时绝缘电阻值不变。","answer":false,"explain":"错。温度升高时绝缘电阻值降低（绝缘介质导电性增强）。"},{"no":40,"stem":"变压器大盖沿气体继电器方向坡度为2%-4%。","answer":false,"explain":"错。变压器大盖沿气体继电器方向应有1%-1.5%的坡度（便于气体汇集到继电器），2%-4%过大。"},{"no":41,"stem":"有载调压变压器在无载时改变分接头。","answer":false,"explain":"错。有载调压变压器可在带负荷（有载）状态下改变分接头；无载调压必须停电后进行。"},{"no":42,"stem":"变压器净油器作用是吸收油中水分。","answer":true,"explain":"对。净油器内装吸附剂（硅胶、活性氧化铝），用以吸收油中水分和杂质，减缓油质劣化。"},{"no":43,"stem":"电器仪表准确度等级分7个级。","answer":true,"explain":"对。电气仪表准确度等级分7级：0.1、0.2、0.5、1.0、1.5、2.5、5.0级。"},{"no":44,"stem":"仪表的误差有：本身固有误差和外部环境造成的附加误差。","answer":true,"explain":"对。仪表误差包括本身固有误差（基本误差）和外部环境（温度、磁场、湿度等）造成的附加误差。"},{"no":45,"stem":"准确度为0.1级的仪表，其允许的基本误差不超过±0.1%。","answer":true,"explain":"对。准确度等级数值即允许的基本误差百分数，0.1级仪表允许基本误差不超过±0.1%。"},{"no":46,"stem":"在中性点直接接地系统中，零序电流互感器一般接在中性点的接地线上。","answer":true,"explain":"对。中性点直接接地系统中，零序电流互感器接在中性点接地线上，用于检测零序电流实现接地保护。"},{"no":47,"stem":"电压互感器又称仪表变压器，也称TV，工作原理、结构和接线方式都与变压器相同。","answer":true,"explain":"对。电压互感器（TV/PT）又称仪表变压器，工作原理、结构和接线方式都与普通变压器相同。"},{"no":48,"stem":"电压互感器与变压器主要区别在于容量小。","answer":true,"explain":"对。电压互感器与普通变压器主要区别在于容量很小（仅几十到几百伏安），且工作于空载状态。"},{"no":49,"stem":"电压互感器的二次绕组匝数少，经常工作在相当于空载的工作状态下。","answer":true,"explain":"对。电压互感器二次绕组匝数少（二次电压低），负载阻抗很大，经常工作在相当于空载的状态。"},{"no":50,"stem":"电压互感器二次负载变化时，电压基本维持不变，相当于一个电压源。","answer":true,"explain":"对。电压互感器二次负载在额定范围内变化时二次电压基本不变，相当于一个电压源。"},{"no":51,"stem":"电压互感器的用途是把一次大电流按一定比例变小，用于测量等。","answer":false,"explain":"错。把一次大电流按比例变小的是电流互感器；电压互感器是把高电压变为低电压（100V）。"},{"no":52,"stem":"电压互感器可以隔离高压，保证了测量人员和仪表及保护装置的安全。","answer":true,"explain":"对。电压互感器将高电压变为低电压，隔离高压，保证测量人员和二次设备安全。"},{"no":53,"stem":"电压互感器的互感比即为一、二次额定电压之比。","answer":true,"explain":"对。互感比（变比）即一、二次额定电压之比。"},{"no":54,"stem":"电流互感器是把大电流变为小电流的设备，又称变流器。","answer":true,"explain":"对。电流互感器（CT/TA）又称变流器，把大电流变为标准小电流（5A或1A）。"},{"no":55,"stem":"电流互感器的一次匝数很多，二次匝数很少。","answer":false,"explain":"错。电流互感器一次匝数很少（常为一匝或几匝），二次匝数很多。这样才能把大电流变为小电流。"},{"no":56,"stem":"电流互感器可以把高电压与仪表和保护装置等二次设备隔开，保证了测量人员与仪表的安全。","answer":true,"explain":"对。电流互感器将高电压回路与二次设备隔离，保证人员和仪表安全。"},{"no":57,"stem":"电流互感器二次应接地。","answer":true,"explain":"对。电流互感器二次必须有一点可靠接地，防止一二次绝缘击穿时高压窜入二次回路。"},{"no":58,"stem":"电流互感器的二次开路不会对设备产生不良影响。","answer":false,"explain":"错。电流互感器二次开路危害极大：铁芯严重过热、二次侧感应出高电压，危及人身和设备。严禁开路。"},{"no":59,"stem":"电流互感器和电压互感器的二次可以互相连接。","answer":false,"explain":"错。电流互感器与电压互感器二次回路严禁互相连接，否则会造成短路或反充电事故。"},{"no":60,"stem":"电流互感器二次回路上工作时，禁止采用熔丝或导线缠绕方式短接二次回路。","answer":true,"explain":"对。电流互感器二次回路上工作时，严禁用熔丝或导线缠绕方式短接，必须使用专用短路片或短路线可靠短接。"},{"no":61,"stem":"禁止在电流互感器与临时短路点之间进行工作。","answer":true,"explain":"对。禁止在电流互感器与临时短路点之间进行工作，防止作业中造成二次开路。"},{"no":62,"stem":"隔离开关可以切无故障电流。","answer":false,"explain":"错。隔离开关无灭弧装置，不能切断负荷电流和短路电流，更不能切除故障电流。"},{"no":63,"stem":"用隔离开关可以断开系统中发生接地故障的消弧线圈。","answer":false,"explain":"错。系统发生接地故障时，严禁用隔离开关断开消弧线圈（消弧线圈带有电流，隔离开关不能带电流操作）。"},{"no":64,"stem":"隔离开关可以拉合无故障的电压互感器和避雷器。","answer":true,"explain":"对。隔离开关可以拉合无故障的电压互感器和避雷器（因其空载电流极小）。"},{"no":65,"stem":"隔离开关不仅用来倒闸操作，还可以切断负荷电流。","answer":false,"explain":"错。隔离开关仅用于倒闸操作和隔离电源形成明显断开点，不能切断负荷电流（无灭弧能力）。"},{"no":66,"stem":"隔离开关可以拉合主变压器中性点。","answer":true,"explain":"对。隔离开关可以拉合主变压器中性点接地刀闸（正常时中性点无电流或电流极小）。"},{"no":67,"stem":"变压器的铁芯不能多点接地。","answer":true,"explain":"对。变压器铁芯必须一点接地，不能多点接地。多点接地会形成环流导致局部过热。"},{"no":68,"stem":"变压器在空载时，一次绕组中没有电流流过。","answer":false,"explain":"错。变压器空载时一次绕组有空载（励磁）电流流过，用于建立主磁通。"},{"no":69,"stem":"装有并联电容器发电机就可以少发无功。","answer":true,"explain":"对。并联电容器就地补偿无功后，发电机（或电源）就少发无功，可提高功率因数、降低损耗。"},{"no":70,"stem":"断路器中的油起冷却作用。","answer":false,"explain":"错。断路器中的油主要起灭弧和绝缘作用，不是冷却作用（变压器油才主要起绝缘冷却作用）。"},{"no":71,"stem":"高压断路器在大修后应调试有关行程。","answer":true,"explain":"对。高压断路器大修后必须调试行程、同期、分合闸速度等机械特性参数。"},{"no":72,"stem":"断路器红灯回路应串有断路器常闭触点。","answer":false,"explain":"错。断路器红灯回路应串有断路器常开（动合）辅助触点——合闸后红灯亮表示合闸位置及跳闸回路完好。"},{"no":73,"stem":"断路器油量过多在遮断故障时会发生爆炸。","answer":true,"explain":"对。断路器油量过多时，遮断故障产生大量气体使油面以上缓冲空间不足，压力剧增可能发生爆炸。"},{"no":74,"stem":"分闸速度过低会使燃弧速度加长，断路器爆炸。","answer":true,"explain":"对。分闸速度过低使电弧燃弧时间加长、热量积聚，可能导致灭弧失败甚至断路器爆炸。"},{"no":75,"stem":"电力企业或者用户违反供用电合同，给对方造成损失的，应当依法承担赔偿责任。","answer":true,"explain":"对。供用电合同具有法律效力，违约造成损失应依法承担赔偿责任。"},{"no":76,"stem":"严禁工作人员在工作中移动或拆除围栏、接地线和标示牌。","answer":true,"explain":"对。严禁工作人员在工作中擅自移动或拆除围栏、接地线和标示牌，这些是保障安全的措施。"},{"no":77,"stem":"雷雨天巡视室外高压设备时，应穿绝缘靴，并不得靠近避雷器和避雷针。","answer":true,"explain":"对。雷雨天巡视室外高压设备应穿绝缘靴，并不得靠近避雷器和避雷针（防止跨步电压和反击）。"},{"no":78,"stem":"用电流表、电压表测负载时，电流表与负载串联，电压表与负载并联。","answer":true,"explain":"对。电流表应与负载串联（测电流），电压表应与负载并联（测电压）。"},{"no":79,"stem":"红灯表示跳闸回路完好，绿灯表示合闸回路完好。","answer":true,"explain":"对。红灯亮表示跳闸回路完好（断路器在合位），绿灯亮表示合闸回路完好（断路器在分位）。"},{"no":80,"stem":"瓦斯保护范围是变压器的外部。","answer":false,"explain":"错。瓦斯保护范围是变压器内部故障（油箱内），不反映外部故障。差动保护才反映保护区内外故障。"},{"no":81,"stem":"零序保护反映的是单相接地故障。","answer":true,"explain":"对。零序保护反映单相接地故障（零序分量只在接地时出现）。"},{"no":82,"stem":"可以直接用隔离开关拉已接地的避雷器。","answer":false,"explain":"错。已接地的避雷器不能用隔离开关直接拉开（接地电流未切断，隔离开关不能带电流操作）。"},{"no":83,"stem":"隔离开关可以拉合空母线。","answer":true,"explain":"对。隔离开关可以拉合空母线（空载母线，电容电流很小，在允许范围内）。"},{"no":84,"stem":"备用母线无须试充电，可以直接投入运行。","answer":false,"explain":"错。备用母线投入运行前必须试充电，以检查其绝缘是否良好，不得直接投入。"},{"no":85,"stem":"安装接地线要先装导体端，后装接地端。","answer":false,"explain":"错。装设接地线必须先装接地端、后装导体端；拆除时顺序相反（先拆导体端、后拆接地端）。"},{"no":86,"stem":"变比不相同的变压器不能并列运行。","answer":true,"explain":"对。变比不相同的变压器并列运行会产生环流，增加损耗甚至烧毁，故不能并列。"},{"no":87,"stem":"装设接地线要先装接地端、后装导体端，先装中相、后装边相的顺序，拆除顺序相。","answer":true,"explain":"对。装设接地线顺序：先接地端后导体端，先装中相后装边相；拆除顺序相反。"},{"no":88,"stem":"变电站主变压器构架等装设的固定扶梯，应悬挂“止步，高压危险”标示牌。","answer":false,"explain":"错。主变压器构架等固定扶梯应悬挂'禁止攀登，高压危险'标示牌，而非'止步，高压危险'。"},{"no":89,"stem":"不允许交、直流回路共用一条电缆。","answer":true,"explain":"对。交、直流回路严禁共用一条电缆，防止相互干扰造成保护误动。"},{"no":90,"stem":"值班运行人员与调度员进行倒闸操作联系时，要首先互相汇报站名、姓名。","answer":true,"explain":"对。值班运行人员与调度员进行倒闸操作联系时，首先互相汇报站名、姓名，严格执行发令复诵制度。"},{"no":91,"stem":"线路停电时，必须按照断路器、母线侧隔离开关、负荷侧隔离开 关的顺序操作，送电时相反。","answer":false,"explain":"错。线路停电操作顺序：先断开断路器，再拉开负荷侧隔离开关，最后拉开电源侧隔离开关（题目中母线侧与负荷侧顺序写反了）。送电顺序相反。"},{"no":92,"stem":"隔离开关可以拉合负荷电流和接地故障电流。","answer":false,"explain":"错。隔离开关不能拉合负荷电流和接地故障电流，只能拉合空载设备和小电流。"},{"no":93,"stem":"只有油断路器可以在断路器现场就地用手动操作方式进行停送电 操作。","answer":false,"explain":"错。任何断路器（包括油断路器）都严禁在现场就地手动操作停送电（应远方操作，防止故障时伤人）。"},{"no":94,"stem":"拆除接地线要先拆接地端后拆导体端。","answer":false,"explain":"错。拆除接地线应先拆导体端、后拆接地端，与装设顺序相反。"},{"no":95,"stem":"倒闸操作需要开（合）的隔离开关，在操作前已经在开（合）位 的则在操作票中不用再列入。","answer":false,"explain":"错。操作票中需要操作的项目，即使操作前已在开（合）位，仍须列入操作票并逐项检查确认。"},{"no":96,"stem":"操作开关时，操作中操作人要检查灯光、表计是否正确。","answer":true,"explain":"对。操作开关时，操作人应检查灯光、表计是否正确，确认断路器实际动作到位。"},{"no":97,"stem":"装设接地线要先装边相后装中相。","answer":false,"explain":"错。装设接地线应先装中相，后装边相（先装离人体较远的中相，保证安全）。"},{"no":98,"stem":"发生触电时，电流作用的时间越长，伤害越重。","answer":true,"explain":"对。触电伤害程度与电流大小、通电时间、电流路径等有关，时间越长伤害越重。"},{"no":99,"stem":"禁止摆动伤员头部呼叫伤员。","answer":true,"explain":"对。禁止摆动伤员头部呼叫伤员，以免加重可能存在的颈椎损伤。"},{"no":100,"stem":"胸外按压必须有效，有效的标志是按压过程中可以感觉到呼吸。","answer":false,"explain":"错。胸外按压有效的标志是按压时可触及颈动脉搏动（及面色转红、瞳孔缩小等），不是感觉到呼吸。"},{"no":101,"stem":"救护触电伤员切除电源时，有时会同时使照明失电，因此应同时考虑事故照明，应急灯等临时照明。","answer":true,"explain":"对。切除电源时可能同时切断照明，故应事先考虑事故照明、应急灯等临时照明。"},{"no":102,"stem":"在口对口人工呼吸最初两次吹气后，试测颈动脉两侧仍无搏动可以判定心跳已经停止应继续对伤员吹气。","answer":false,"explain":"错。口对口人工呼吸最初两次吹气后试测颈动脉仍无搏动，应判定心跳停止，立即进行胸外按压（配合人工呼吸），而不是继续单纯吹气。"},{"no":103,"stem":"编制变电站电气主接线运行方式时，要力求满足供电可靠性、灵活性和经济性等要。","answer":true,"explain":"对。电气主接线运行方式应满足供电可靠性、灵活性和经济性要求。"},{"no":104,"stem":"在事故处理或进行倒闸操作时，不得进行交接班，交接班时发生事故，应立即停止交接班，并由交班人员处理，接班人员在交班值长指挥下协助工作。","answer":true,"explain":"对。事故处理或倒闸操作时不得交接班；交接班时发生事故应立即停止交接，由交班人员处理、接班人员协助。"},{"no":105,"stem":"操作开关时，操作中操作人员只需检查表计是否正确。","answer":false,"explain":"错。操作开关时既要看表计也要看灯光指示，二者都要检查，不能只看表计。"},{"no":106,"stem":"断路器操作把手在预备合闸位置时绿灯闪光，在预备跳闸位置时红灯闪光。","answer":true,"explain":"对。断路器操作把手在预备合闸位置时绿灯闪光，预备跳闸位置时红灯闪光，作为操作提示。"},{"no":107,"stem":"各电压等级母线、母联断路器、旁路断路器、母联兼旁路断路器的名称必须有电压等级。","answer":true,"explain":"对。各电压等级母线、母联断路器等设备的名称必须冠以电压等级，避免混淆。"},{"no":108,"stem":"隔离开关操作需要开（合）的隔离开关，在操作前，已经开（合）位时，并列入操作票中。","answer":true,"explain":"对。操作票中应列入需要操作的隔离开关，即使操作前已在开（合）位也要列入并核对。"},{"no":109,"stem":"每项操作完毕，监护人核对操作无误后，在操作票操作栏内打一个红色“对号”，并记录操作时间。","answer":true,"explain":"对。每项操作完毕，监护人核对无误后在操作票上打红色'√'并记录操作时间。"},{"no":110,"stem":"熟练的值班员，简单的操作可不用操作票，而凭经验和记忆进行操作。","answer":false,"explain":"错。任何倒闸操作都必须填写操作票，严禁凭经验和记忆无票操作（事故处理等特殊情况除外）。"},{"no":111,"stem":"操作票可以由操作人填写，也可以由监护人填写。","answer":false,"explain":"错。操作票应由操作人填写，监护人审核，不能由监护人填写（失去审核意义）。"},{"no":112,"stem":"操作必须接操作票的顺序依次操作，不得跳项，漏项，不得擅自更改操作顺序。","answer":true,"explain":"对。操作必须按操作票顺序依次进行，不得跳项、漏项或擅自更改顺序。"},{"no":113,"stem":"操作过程中若操作人有事，可以换其它人操作。","answer":false,"explain":"错。操作过程中不得更换操作人，确需更换时必须重新模拟预演。"},{"no":114,"stem":"操作过程中，监护人若不动口，则操作人不能动手。","answer":true,"explain":"对。监护人不发令（不动口），操作人不能动手，体现监护制度的严肃性。"},{"no":115,"stem":"操作票内所填写的项目必须采用双重名称，即：设备名称和编号。","answer":true,"explain":"对。操作票内项目必须采用双重名称，即设备名称和编号，防止走错间隔。"},{"no":116,"stem":"雷雨天，禁止对设备进行摇测绝缘电阻。","answer":true,"explain":"对。雷雨天禁止摇测绝缘电阻，防止雷电过电压伤人并影响测量准确性。"},{"no":117,"stem":"对于仅是单一的操作、事故处理操作、拉开接地刀闸和拆除仅有的一组接地线的操作，可不必填写操作票，但应记入操作记录本。","answer":true,"explain":"对。单一操作、事故处理、拉开接地刀闸和拆除仅有的一组接地线，可不用操作票，但应记入操作记录本。"},{"no":118,"stem":"变配电所操作中，接挂或拆卸地线、验电及装拆电压互感器回路的熔断器等项目可不填写操作票。","answer":false,"explain":"错。接挂或拆卸地线、验电及装拆电压互感器回路熔断器等项目，属于操作票应填写的重要项目，必须填入操作票。"},{"no":119,"stem":"变电所停电操作，在电路切断后的“验电”工作，可不填入操作票。","answer":false,"explain":"错。停电操作后的'验电'是操作票的重要项目，必须填入操作票，不得省略。"},{"no":120,"stem":"抢救触电伤员中，用兴奋呼吸中枢的可拉明、洛贝林，或使心脏复跳的肾上腺素等强心针剂可代替手工呼吸和胸外心脏挤压两种急救措施。","answer":false,"explain":"错。任何药物都不能代替人工呼吸和胸外心脏挤压（心肺复苏）这两项基本急救措施。"},{"no":121,"stem":"电气设备停电后，在没有断开电源开关和采取安全措施以前，不得触及设备或进入设备的遮栏内，以免发生人身触电事故。","answer":true,"explain":"对。电气设备停电后，在未断开电源开关和采取安全措施前，不得触及设备或进入遮栏，防止触电。"},{"no":122,"stem":"工作票签发人可以列入工作值班人员，参加现场作业。","answer":true,"explain":"对。工作票签发人可以列入工作班成员参加现场作业（但实际工作中应尽量减少兼职以保证监督到位）。"},{"no":123,"stem":"工作票终结手续应由工作值班人员负责办理。","answer":false,"explain":"错。工作票终结手续应由工作负责人（工作值班人员）办理的说法不准确，终结应由工作负责人与工作许可人共同办理，双方签字。"},{"no":124,"stem":"电工不允许单独作业。","answer":true,"explain":"对。电工不允许单独作业，电气作业至少两人（一人操作、一人监护），保证安全。"},{"no":125,"stem":"电气设备使用完毕应及时拔掉插头。","answer":true,"explain":"对。电气设备使用完毕应及时拔掉插头，既安全又节能。"},{"no":126,"stem":"安装锯条时，齿尖应向后。","answer":false,"explain":"错。安装锯条时齿尖应向前（朝推锯方向），这样推锯时才起切削作用。"},{"no":127,"stem":"用电工刀剖削导线绝缘层时，应让刀口朝内进行剖削。","answer":false,"explain":"错。用电工刀剖削导线绝缘层时，刀口应朝外（向外剖削），防止伤及手部或损伤线芯。"},{"no":128,"stem":"在线路、设备上工作时，只要验证无电就可以开始工作。","answer":false,"explain":"错。在线路、设备上工作，仅验证无电是不够的，还必须停电、验电、装设接地线、悬挂标示牌和装设遮栏等，完成全部安全措施方可工作。"},{"no":129,"stem":"在测量绝缘电阻前，必须将被测设备对地放电，测量中禁止他人接近设备。","answer":true,"explain":"对。测量绝缘电阻前必须将被测设备对地放电（防止残余电荷伤人和影响读数），测量中禁止他人接近。"},{"no":130,"stem":"在用兆欧表测试前，必须使设备带电测试才准确。","answer":false,"explain":"错。兆欧表测试前必须使设备完全断电并放电，严禁带电测试（既危险又测不准）。"},{"no":131,"stem":"操作跌落式熔断器时应先拉中相，再拉下风侧一相，最后拉上风侧一相。","answer":true,"explain":"对。操作跌落式熔断器应先拉中相，再拉下风侧一相，最后拉上风侧一相，可减小电弧吹向人身和相邻相的风险。"},{"no":132,"stem":"停电时，先断开断路器，后拉开负荷侧隔离开关，最后拉开电源侧隔离开关。","answer":true,"explain":"对。停电操作顺序：先断开断路器，再拉开负荷侧隔离开关，最后拉开电源侧隔离开关。送电顺序相反。"},{"no":133,"stem":"操作票应填写设备的双重名称，即设备的名称和编号。","answer":true,"explain":"对。操作票应填写设备双重名称（设备名称和编号）。"},{"no":134,"stem":"电气设备倒闸操作必须由两人进行，即一人操作，一人监护。","answer":true,"explain":"对。倒闸操作必须两人进行：一人操作、一人监护。"},{"no":135,"stem":"每份操作票只能填写一个操作任务。","answer":true,"explain":"对。每份操作票只能填写一个操作任务，避免混淆。"},{"no":136,"stem":"操作票应用钢笔或圆珠笔逐项填写。用计算机开出的操作票应与手写格式一致。","answer":true,"explain":"对。操作票应用钢笔或圆珠笔逐项填写，计算机开出的操作票应与手写格式一致。"},{"no":137,"stem":"处理事故时不需填写操作票。","answer":true,"explain":"对。事故处理时可不填写操作票（但须有调度命令），事后应记入记录簿。"},{"no":138,"stem":"遮栏与带电设备的距离不小于规定的安全距离。","answer":true,"explain":"对。遮栏与带电设备的距离不得小于规定的安全距离，保证人员安全。"},{"no":139,"stem":"装设接地线，应先接导线端后接接地端。","answer":false,"explain":"错。装设接地线应先接接地端，后接导体端；拆除顺序相反。"},{"no":140,"stem":"凡影响变配电所电源投切或改变电力系统运行方式的倒闸操作等较复杂的操作项目，均必须填用操作票。","answer":true,"explain":"对。影响电源投切或改变系统运行方式的复杂操作，均必须填用操作票。"},{"no":141,"stem":"为了解救触电人员，可以不经允许，立即断开电源，事后立即向上级汇报。","answer":true,"explain":"对。解救触电人员可以不经允许立即断开电源（生命优先），事后立即汇报。"},{"no":142,"stem":"如果发现触电者触电后当时已经没有呼吸或心跳，就可以放弃抢救了。","answer":false,"explain":"错。触电者无呼吸或心跳时绝不能放弃抢救，应立即进行心肺复苏并呼叫急救，坚持抢救至专业人员到达。"},{"no":143,"stem":"倒闸操作前，应先在模拟图板上进行核对性模拟预演。","answer":true,"explain":"对。倒闸操作前应先在模拟图板上进行核对性模拟预演，确认操作顺序无误。"},{"no":144,"stem":"隔离开关与熔断器串联使用时，送电的操作顺序是先合上隔离开关后装上熔断器。","answer":false,"explain":"错。隔离开关与熔断器串联使用时，送电应先装上熔断器，再合上隔离开关（避免带负荷装熔断器产生电弧）。"},{"no":145,"stem":"装设、拆除临时接地线时，应使用绝缘棒或绝缘手套。","answer":true,"explain":"对。装拆临时接地线时应使用绝缘棒或戴绝缘手套，防止触电。"},{"no":146,"stem":"送电时，先合上电源侧隔离开关，再合上负荷侧隔离开关，最后合上断路器。","answer":true,"explain":"对。送电操作顺序：先合电源侧隔离开关，再合负荷侧隔离开关，最后合断路器。"},{"no":147,"stem":"设备定期试验与切换应填写操作票，应做好记录。","answer":true,"explain":"对。设备定期试验与切换应填写操作票并做好记录。"},{"no":148,"stem":"当万用表的不同电阻量程测量二极管正反向电阻时，其读数不相同。","answer":true,"explain":"对。用万用表不同电阻挡测二极管正反向电阻时读数不同（二极管是非线性元件，正向电阻小、反向电阻大）。"},{"no":149,"stem":"电流表应并联在电路中使用。","answer":false,"explain":"错。电流表应串联在电路中（内阻极小），并联会造成短路。"},{"no":150,"stem":"配电变压器低压侧中性点接地叫做保护接地。","answer":false,"explain":"错。配电变压器低压侧中性点接地属于工作接地（保证系统电位参考和为单相负荷提供回路），不是保护接地。"},{"no":151,"stem":"隔离开关主要是用来隔离电路形成可见的空气间隔。","answer":true,"explain":"对。隔离开关主要用来隔离电路、形成可见的空气间隔（明显断开点）。"},{"no":152,"stem":"高压跌落式熔断器必须采用专用的绝缘操作棒进行操作。","answer":true,"explain":"对。高压跌落式熔断器必须用专用绝缘操作棒（令克棒）操作，保证人身安全。"},{"no":153,"stem":"变压器电压高的一侧叫一次侧，电压低的一侧叫做二次侧。","answer":false,"explain":"错。变压器电压高的一侧不一定是'一次侧'——一次侧、二次侧按功率传递方向定义（接电源侧为一次侧），升压变压器低压侧才是一次侧。"},{"no":154,"stem":"在选用低压断路器时断路器的额定电压可以小于电源和负载的额定电压。","answer":false,"explain":"错。低压断路器的额定电压不得小于电源和负载的额定电压，否则绝缘和灭弧能力不足。"},{"no":155,"stem":"低压电器可分为开关电器和保护电器。","answer":true,"explain":"对。低压电器按用途可分为开关电器（刀开关、接触器等）和保护电器（熔断器、热继电器等）。"},{"no":156,"stem":"直接将电能送到用户用电设备的网络称为配电网络。","answer":true,"explain":"对。直接将电能送到用户用电设备的网络称为配电网络（配电网）。"},{"no":157,"stem":"变压器容量在100kVA以下，其一次侧熔丝可按2～3倍额定电流选用。","answer":true,"explain":"对。100kVA以下变压器一次侧熔丝可按2-3倍额定电流选用（小容量变压器需躲过励磁涌流）。"},{"no":158,"stem":"设备一经合闸便带电运行的状态称运行状态。","answer":false,"explain":"错。设备一经合闸便带电运行的状态称为热备用状态，不是运行状态。运行状态是指设备已合闸带电并带负荷运行。"},{"no":159,"stem":"绝缘材料是绝对不导电的材料。","answer":false,"explain":"错。绝缘材料并非绝对不导电，仍有极微小的漏电流；在高电压下也可能被击穿。"},{"no":160,"stem":"当交流电源电压加到变压器的一次绕组后，变压器的二次侧绕组与外电路负荷断开，会有电能输出。","answer":false,"explain":"错。二次侧与外电路负荷断开（空载）时，二次绕组有感应电动势但没有电流，故无电能输出。"},{"no":161,"stem":"SF6气体是一种无色、无臭、无毒的气体，即使在电弧作用下，分解的气体也无毒。","answer":false,"explain":"错。SF6气体本身无色无臭无毒，但在电弧作用下会分解产生有毒的氟化物（如SF4、SOF2等），需注意防护。"},{"no":162,"stem":"变压器匝数多的一侧电流大，电压高。","answer":false,"explain":"错。变压器匝数多的一侧电压高、电流小；匝数少的一侧电压低、电流大（功率守恒）。"},{"no":163,"stem":"热备用状态。设备一经合闸便带电运行的状态称热备用状态。","answer":true,"explain":"对。热备用状态指设备一经合闸便带电运行的状态（断路器断开，隔离开关合上，随时可送电）。"},{"no":164,"stem":"高压配电装置，主要用于配电系统作接受与分配电能之用。","answer":true,"explain":"对。高压配电装置用于配电系统中接受与分配电能。"},{"no":165,"stem":"人体与带电体的直接接触电击可分为跨步电压电击、接触电压电击。","answer":false,"explain":"错。人体与带电体直接接触的电击分为单相电击和两相电击；跨步电压电击和接触电压电击属于间接接触电击。"},{"no":166,"stem":"变压器的变比等于一、二次侧感应电势瞬时值之比。","answer":false,"explain":"错。变压器变比等于一、二次侧感应电动势（电压）的有效值之比，不是瞬时值之比。"},{"no":167,"stem":"电压互感器的容量是指其二次绕组允许接入的负载功率。","answer":true,"explain":"对。电压互感器容量指其二次绕组允许接入的负载功率（伏安数）。"},{"no":168,"stem":"降低导线重量，电流密度增大，负载损耗同时下降。","answer":false,"explain":"错。降低导线重量（减小截面）会使电流密度增大、电阻增大，负载损耗（铜损 I²R）反而上升。"},{"no":169,"stem":"电流互感器、电压互感器、二次绕组或铁芯必须有一点可靠接地。","answer":true,"explain":"对。电流互感器、电压互感器的二次绕组或铁芯必须有一点可靠接地，保证安全。"},{"no":170,"stem":"绝缘材料受潮后的绝缘电阻减小。","answer":true,"explain":"对。绝缘材料受潮后绝缘电阻显著减小，绝缘性能下降，故电气设备要防潮。"},{"no":171,"stem":"电压互感器一次与主电路串联。","answer":false,"explain":"错。电压互感器一次绕组应与主电路并联（测电压并联），不是串联。"},{"no":172,"stem":"由发电、送电、变电、配电和用电组成的整体称为电力系统。","answer":true,"explain":"对。电力系统由发电、送电（输电）、变电、配电和用电组成的整体。"},{"no":173,"stem":"在低压配电系统中，三眼插座的N线与PE线应直接相连。","answer":false,"explain":"错。低压配电系统中三眼插座的N线（工作零线）与PE线（保护零线）严禁直接相连，否则可能导致设备外壳带电。"},{"no":174,"stem":"电压比额定值高10%时，白炽灯的寿命将下降50%。","answer":true,"explain":"对。白炽灯对电压敏感：电压高于额定值10%时寿命约下降50%（电压升高发光效率提高但寿命急剧缩短）。"},{"no":175,"stem":"大型电力系统的优点之一是：可以提高运行的灵活性，减少系统的备用容量。","answer":true,"explain":"对。大型电力系统优点：可提高运行灵活性、减少备用容量（系统越大负荷互补性越好，备用可共享）。"},{"no":176,"stem":"当人体同时接触带电设备或线路中的两相导体时，电流从一相导体经人体流入另一相导体，构成闭合回路的电击事故称为两相电击。","answer":true,"explain":"对。人体同时接触两相导体，电流从一相经人体流入另一相构成回路，称为两相电击（最危险，承受线电压）。"},{"no":177,"stem":"变压器内部故障及各部件过热可能引起一系列的气味、颜色的变化。","answer":true,"explain":"对。变压器内部故障及各部件过热会引起油色变深、产生焦糊气味等变化，巡视时可据此发现异常。"},{"no":178,"stem":"电气连接点接触不良时，会产生电火花。","answer":true,"explain":"对。电气连接点接触不良时接触电阻增大、发热，严重时产生电火花，是电气火灾的常见隐患。"},{"no":179,"stem":"在低压配电系统中装设剩余电流保护装置只能防止直接接触电击事故。","answer":false,"explain":"错。剩余电流保护装置（漏电保护器）不仅能防止直接接触电击，也能防止间接接触电击和电气火灾。"},{"no":180,"stem":"空气中的氧和温度是引起绝缘油老化的主要因素。","answer":true,"explain":"对。空气中的氧和温度是引起绝缘油老化的主要因素（氧化和高温加速油质劣化）。"},{"no":181,"stem":"拧紧螺母时,严禁用套筒延长手柄长度来加大拧紧力。","answer":true,"explain":"对。拧紧螺母严禁用套筒延长手柄加大拧紧力，否则会过载损坏螺纹或螺栓。"},{"no":182,"stem":"钳形电流表是在不断开电路情况下进行测量，且测量的精度也很高。","answer":false,"explain":"错。钳形电流表可不断开电路测量，但精度较低（一般2.5-5级），不宜用于精密测量。"},{"no":183,"stem":"铜的导电性能在金属中是最好的。","answer":false,"explain":"错。银的导电性能最好，铜次之，铝再次。银因价格昂贵不常用。"},{"no":184,"stem":"“安培定则”用于判定电流产生磁场的方向。","answer":true,"explain":"对。安培定则（右手螺旋定则）用于判定电流产生磁场的方向。"},{"no":185,"stem":"用万用表测电阻时不允许带电测量。","answer":true,"explain":"对。用万用表测电阻时严禁带电测量，否则会损坏仪表且读数无意义。"},{"no":186,"stem":"电压表使用后应将转换开关置于高压挡位。","answer":true,"explain":"对。电压表使用后应将转换开关置于高压挡（或OFF挡），防止下次测量时误用小量程损坏仪表。"},{"no":187,"stem":"安装螺口灯座时，由开关处来的相线须接于螺口灯座的中心接线端。","answer":true,"explain":"对。安装螺口灯座时，由开关引来的相线（火线）须接于中心接线端，螺纹圈接零线，保证更换灯泡时安全。"},{"no":188,"stem":"按钮是手按下即动作，手松开即释放复位的小电流开关电器。","answer":true,"explain":"对。按钮是手按下即动作、手松开即复位的小电流开关电器，用于发出控制信号。"},{"no":189,"stem":"保护接地的接地电阻不得小于4Ω。","answer":false,"explain":"错。保护接地的接地电阻不得大于4Ω（越小越安全），不是不小于。"},{"no":190,"stem":"保护零线在短路电流作用下不能熔断。","answer":true,"explain":"对。保护零线（PE线）在短路电流作用下不能熔断，以保证故障回路畅通、保护装置可靠动作。"},{"no":191,"stem":"变压器的主要品种是电力变压器。","answer":true,"explain":"对。变压器的主要品种是电力变压器（用于输配电系统变换电压）。"},{"no":192,"stem":"变压器二次侧额定电压是变压器额定运行时二次侧的电压。","answer":false,"explain":"错。变压器二次侧额定电压是一次侧加额定电压、二次侧空载时的电压（不是额定运行带负荷时的电压，带负荷时因内阻抗压降会略低）。"},{"no":193,"stem":"并联电阻的等效电阻值小于并联中任一电阻的阻值。","answer":true,"explain":"对。并联电阻的等效电阻值小于其中任一电阻的阻值。"},{"no":194,"stem":"不同电压等级的绝缘夹钳，其绝缘部分长度是不一样的。","answer":true,"explain":"对。不同电压等级的绝缘夹钳，其绝缘部分长度不同（电压越高绝缘部分越长）。"},{"no":195,"stem":"变压器不但可以改变交流电压，也可以用来改变直流电压。","answer":false,"explain":"错。变压器只能改变交流电压，不能改变直流电压（直流磁通不变，无法感应电动势）。"},{"no":196,"stem":"串联电阻的等效电阻值大于串联中任一电阻的阻值。","answer":true,"explain":"对。串联电阻的等效电阻值大于其中任一电阻的阻值（等于各电阻之和）。"},{"no":197,"stem":"刀开关、铁壳开关、组合开关的额定电流要大于实际电路电流。","answer":true,"explain":"对。刀开关、铁壳开关、组合开关的额定电流应大于实际电路电流，留有余量。"},{"no":198,"stem":"点动控制，就是点一下按钮就可以启动并运转的控制方式。","answer":false,"explain":"错。点动控制是按下按钮电机运转、松开按钮电机即停转的控制方式，不会自保持运转。"},{"no":199,"stem":"电荷移动的方向就是电流方向。","answer":false,"explain":"错。规定正电荷移动的方向为电流方向，不是电荷（电子）移动的方向。"},{"no":200,"stem":"电流继电器线圈串接于负载电路中，电压继电器线圈并接于被测电路的两端。","answer":true,"explain":"对。电流继电器线圈串接于负载电路中（反映电流），电压继电器线圈并接于被测电路两端（反映电压）。"},{"no":201,"stem":"电流流过电阻产生电位降。","answer":true,"explain":"对。电流流过电阻时沿电流方向电位降低，产生电位降（电压降）。"},{"no":202,"stem":"电流在外电路中从高电位流向低电位。","answer":true,"explain":"对。外电路中电流从高电位流向低电位（电源内部则由低到高，靠电源力推动）。"},{"no":203,"stem":"电路中电位是一个相对值，它不随参考点的改变而改变。","answer":false,"explain":"错。电位是相对值，随参考点改变而改变；电压（电位差）才是绝对值，不随参考点改变。"},{"no":204,"stem":"电路中任意两点间的电位差与电位参考点的选择有关。","answer":false,"explain":"错。电路中任意两点间的电位差（电压）与电位参考点的选择无关。"},{"no":205,"stem":"电源将其他形式的能转换成电能，电路中负载将电能转换成其他形式的能。","answer":true,"explain":"对。电源将其他形式能量转换为电能，负载将电能转换为其他形式能量（机械能、热能、光能等）。"},{"no":206,"stem":"变压器的额定容量是变压器额定运行时二次侧的容量。","answer":true,"explain":"对。变压器额定容量指额定运行时的视在功率（铭牌容量，单位kVA），即二次侧输出容量。"},{"no":207,"stem":"电阻并联时，电阻值小的电阻通过的电流大。","answer":true,"explain":"对。电阻并联时各支路电压相等，由 I=U/R，电阻值小的支路电流大。"},{"no":208,"stem":"各个电气设备的金属外壳可以相互串接后接地。","answer":false,"explain":"错。各电气设备的金属外壳严禁相互串接后接地，必须各自单独接地（或接保护零线），否则一处断开会使后续设备失去保护。"},{"no":209,"stem":"在直流电路的电源中,把电流流出的一端叫电源的正极。","answer":true,"explain":"对。直流电路中把电流流出的一端叫电源的正极。"},{"no":210,"stem":"接触器除通断电路外，还具备短路和过载的保护作用。","answer":false,"explain":"错。接触器用于频繁通断电路，但不具备短路和过载保护功能（需配熔断器、热继电器等保护电器）。"},{"no":211,"stem":"欠电压继电器和零压继电器的动作电压是相同的。","answer":false,"explain":"错。欠电压继电器在电压降至某一数值时动作，零压继电器在电压接近零时动作，两者动作电压不同。"},{"no":212,"stem":"热继电器在电路中的接线原则是热元件串联在主电路中，常开触头串联在控制电路中。","answer":false,"explain":"错。热继电器的接线原则是热元件串联在主电路中，常闭触头串联在控制电路中（过载时常闭触头断开切断控制回路）。"},{"no":213,"stem":"日光灯的镇流器只起限流作用。","answer":false,"explain":"错。日光灯镇流器不仅起限流作用，启动时还产生高压点亮灯管，点燃后起降压限流作用。"},{"no":214,"stem":"日光灯工作时，灯管内没有电流流过。","answer":false,"explain":"错。日光灯工作时灯管内有电流流过（气体放电导通），镇流器正是用来限制这个电流的。"},{"no":215,"stem":"容量较大的接触器的主触头一般采用银及合金制成。","answer":true,"explain":"对。容量较大的接触器主触头一般采用银及银合金制成（导电性好、抗氧化、接触电阻小）。"},{"no":216,"stem":"通电导体中电流大，在磁场中受到的电磁力不一定就大。","answer":true,"explain":"对。通电导体在磁场中的受力 F=BILsinθ，不仅与电流大小有关，还与磁感应强度、导体长度及与磁场的夹角有关，故电流大受力不一定大。"},{"no":217,"stem":"变压器的容量是指变压器的视在功率。","answer":true,"explain":"对。变压器容量指其视在功率（单位kVA或MVA）。"},{"no":218,"stem":"同一电源的正极电位永远高于其负极电位。","answer":true,"explain":"对。同一电源的正极电位永远高于负极电位（电动势维持两极间电位差）。"},{"no":219,"stem":"为了提高沿面闪络电压，必须保持固体绝缘表面的清洁和干燥。","answer":true,"explain":"对。保持固体绝缘表面清洁和干燥可提高沿面闪络电压，防止污闪事故。"},{"no":220,"stem":"稳压电源输出的电压值是恒定不变的。","answer":false,"explain":"错。稳压电源输出电压只是相对稳定，仍会随输入电压和负载变化而有微小波动，不是绝对恒定不变。"},{"no":221,"stem":"习惯上规定电流的方向都是电子移动的方向。","answer":false,"explain":"错。习惯上规定电流方向为正电荷移动的方向，与电子移动方向相反。"},{"no":222,"stem":"一根钢管内只可以穿入一相电源相线。","answer":false,"explain":"错。一根钢管内可以穿入同一回路的所有相线（含零线），因为交变磁场相互抵消，不会因涡流发热。严禁的是单根相线单独穿管。"},{"no":223,"stem":"仪表的准确度等级越高，测量的结果就会越准确。","answer":false,"explain":"错。仪表准确度等级高只说明基本误差小，实际测量准确度还与量程选择、读数、环境、测量方法等有关，选错量程时高精度仪表也可能误差很大。"},{"no":224,"stem":"用冲击电钻钻墙孔时，要使用专用的冲击钻头。","answer":true,"explain":"对。冲击电钻钻墙孔应使用专用冲击钻头（硬质合金钻头），普通钻头无法胜任。"},{"no":225,"stem":"用活扳手紧固螺母时，其用力旋动的方向是有要求的。","answer":true,"explain":"对。用活扳手紧固螺母时用力方向有要求，应使作用力朝向固定钳口（活动钳口受拉），否则易损坏扳手或伤手。"},{"no":226,"stem":"用机械万用表欧姆挡测电阻前，每次改挡后都必须重新进行欧姆调零。","answer":true,"explain":"对。机械万用表欧姆挡每次改挡后都必须重新欧姆调零（因不同挡位内阻不同）。"},{"no":227,"stem":"用兆欧表测大电容的绝缘电阻，读数后应先断开电容，再停止摇动手柄。","answer":true,"explain":"对。测大电容绝缘电阻后，应先断开电容接线再停止摇动手柄，防止电容通过表头放电损坏兆欧表。"},{"no":228,"stem":"有人说“没有电压就没有电流”，“没有电流就没有电压”。","answer":false,"explain":"错。'没有电压就没有电流'正确（电压是产生电流的原因）；但'没有电流就没有电压'错误，如开路时电源两端有电压但无电流。"},{"no":229,"stem":"在接触器正、反转控制线路中，若正转接触器和反转接触器同时通电会发生两相电源短路。","answer":true,"explain":"对。正反转控制中若正转和反转接触器同时吸合，两相电源会通过主触头直接短路，故必须设置互锁（电气互锁+机械互锁）。"},{"no":230,"stem":"在未使用前，手摇发电机式兆欧表的指针可以指示在标度尺的任意位置。","answer":true,"explain":"对。手摇发电机式兆欧表未使用时指针可停在标度尺任意位置（无游丝定位力矩）。"},{"no":231,"stem":"只有当导体或线圈是闭合电路的一部分时，才能产生电磁感应现象。","answer":false,"explain":"错。只要穿过线圈或导体回路的磁通发生变化，就会产生感应电动势；回路闭合时才有感应电流，开路时只有感应电动势而无电流。"},{"no":232,"stem":"自感电动势是由流过线圈本身的电流发生变化而产生的。","answer":true,"explain":"对。自感电动势是由线圈本身电流变化引起磁通变化而产生的感应电动势。"},{"no":233,"stem":"自感电流的方向总是与外电流的方向相反的。","answer":false,"explain":"错。自感电流方向：电流增大时自感电流与原电流方向相反（阻碍增大），电流减小时方向相同（阻碍减小），不是总是相反。"},{"no":234,"stem":"自感是电磁感应的一种。","answer":true,"explain":"对。自感是电磁感应的一种（因自身电流变化而产生的电磁感应现象）。"},{"no":235,"stem":"用钳形表测量三相交流电流时，夹住一相线读数为本相电流，夹两根相线读数为第三相的线电流值。","answer":true,"explain":"对。钳形表测三相交流电流：夹一相读数为该相电流；夹两相时读数等于第三相的线电流值（相量和）。"},{"no":236,"stem":"电动势的方向规定为由高电位指向低电位。","answer":false,"explain":"错。电动势的方向规定为由低电位指向高电位（电位升高的方向），与电压方向相反。"},{"no":237,"stem":"三相交流电的A相、B相、C相颜色标志分别为红、黄、绿。","answer":false,"explain":"错。三相交流电极性颜色标志：A相黄色、B相绿色、C相红色（黄、绿、红）。"},{"no":238,"stem":"变压器有变换电压、电流和阻抗的作用。","answer":true,"explain":"对。变压器具有变换电压、变换电流和变换阻抗三种作用。"},{"no":239,"stem":"一般的金属材料，温度升高后，导体的电阻值减小了。","answer":true,"explain":"错。一般金属材料温度升高后电阻值增大（正温度系数），不是减小。"},{"no":240,"stem":"1安培电流，表示每分钟通过导线任一截面的电量是1库仑。","answer":false,"explain":"错。1安培表示每秒钟（不是每分钟）通过导线任一截面的电量是1库仑，即 1A=1C/s。"},{"no":241,"stem":"导体的电阻只与导体的材料有关。","answer":false,"explain":"错。导体电阻 R=ρL/S，与材料（电阻率）、长度、截面积有关，还受温度影响。"},{"no":242,"stem":"树脂、橡胶、棉纱、纸、麻、蚕丝、人造丝、石油等都属于有机绝缘材料。","answer":true,"explain":"对。树脂、橡胶、棉纱、纸、麻、蚕丝、人造丝、石油等都属于有机绝缘材料。"},{"no":243,"stem":"上下布置的交流母线时，相序的排列次序是(A)(B)C，由上而下。","answer":true,"explain":"对。上下布置的交流母线，相序排列由上而下为A、B、C相。"},{"no":244,"stem":"电动势与电源端电压之间总是大小相等、方向相反。","answer":false,"explain":"错。电动势与电源端电压只在开路（无电流）时大小相等、方向相反（E=U）；有电流时 U=E−Ir，且数值不等。"},{"no":245,"stem":"从母线做引下线时，面对柜或设备正视方向引下线相序的排列次序是(A)(B)C，由右至左。","answer":false,"explain":"错。从母线做引下线时，面对柜或设备正视方向，引下线相序排列应由左至右为A、B、C相，不是由右至左。"},{"no":246,"stem":"电气设备中的铜铝接头一般是不能直接连接的。","answer":true,"explain":"对。铜铝接头一般不能直接连接，因二者电位不同易产生电化学腐蚀、热胀冷缩系数不同易松动，应采用铜铝过渡接头。"},{"no":247,"stem":"电路中产生感应电流必有感应电动势产生。","answer":true,"explain":"对。电路中有感应电流必然先有感应电动势（电动势是产生电流的原因）。"},{"no":248,"stem":"自动空气开关的瞬时脱扣器在线路上的作用是过载保护。","answer":false,"explain":"错。自动空气开关的瞬时脱扣器在线路上起短路保护作用；过载保护由热脱扣器（延时）完成。"},{"no":249,"stem":"线的作用是平衡电杆各方面的作用力，以防电杆倾倒。","answer":true,"explain":"对。拉线的作用是平衡电杆各方面的作用力，防止电杆倾倒（题干'线'指拉线）。"},{"no":250,"stem":"电缆铠装层主要是用以减少电磁力对电缆的影响。","answer":false,"explain":"错。电缆铠装层主要用以增强电缆的机械强度（抗压、抗拉、防外力损伤），不是减少电磁力影响。"},{"no":251,"stem":"导线接头接触不良往往是电气事故的根源。","answer":true,"explain":"对。导线接头接触不良会增大接触电阻、发热，往往是电气事故和火灾的根源。"},{"no":252,"stem":"两根同规格型号的电缆，其长度长者电阻大。","answer":true,"explain":"对。两根同规格型号电缆，长度长者的电阻大（R=ρL/S）。"},{"no":253,"stem":"正确选择仪表的量程是减少测量误差的基本方法。","answer":true,"explain":"对。正确选择仪表量程（使读数落在刻度后1/3或2/3以上区域）是减少测量误差的基本方法。"},{"no":254,"stem":"电阻串联时，电阻值小的电阻通过的电流大。","answer":false,"explain":"错。电阻串联时各电阻流过同一电流，与阻值大小无关（串联电流处处相等）。阻值大的分压大。"},{"no":255,"stem":"截流导体周围的磁场方向可用左手定则判断。","answer":false,"explain":"错。载流导体周围磁场方向用右手螺旋定则（安培定则）判断；左手定则用于判断导体在磁场中的受力方向。"},{"no":256,"stem":"10kV以上高压电缆均为单芯电缆。","answer":false,"explain":"错。10kV以上高压电缆并非都是单芯电缆，也有三芯电缆（如10kV、35kV三芯电缆广泛使用）。"},{"no":257,"stem":"四芯电缆中，中性线芯主要是流通不平衡的电流。","answer":true,"explain":"对。四芯电缆中的中性线芯主要用于流通三相不平衡电流和单相负荷电流。"},{"no":258,"stem":"放电缆中，电缆可以从电缆盘的上端或下端放出。","answer":false,"explain":"错。敷设电缆时电缆应从电缆盘的上端放出（避免电缆扭绞和受压），不能从下端放出。"},{"no":259,"stem":"一般载流母线会产生振动和声响。","answer":true,"explain":"对。载流母线在交变电磁力作用下会产生振动和声响（尤其在短路电流冲击时更明显）。"},{"no":260,"stem":"绝缘厚度增加一倍，耐压强度一定增加一倍。","answer":false,"explain":"错。绝缘厚度增加一倍，耐压强度不一定成比例增加一倍（还受材料均匀性、电场分布、工艺等因素影响，并非线性关系）。"}]};
